static QQuickItem *item(QQuickItem *root, const QString &name)
{
    if (root->objectName() == name)
        return root;
    for (auto *child : root->childItems())
        if (auto *found = item(child, name))
            return found;
    return nullptr;
}

static void clickReadyItem(QQuickWindow *window, QQuickItem *target, QPointF *dispatchedAt = nullptr)
{
    QVERIFY(target);
    QVERIFY(target->isVisible());
    QVERIFY2(target->width() > 0 && target->height() > 0,
             qPrintable(QStringLiteral("ZERO-SIZE %1 %2x%3 visible=%4 enabled=%5")
                        .arg(target->objectName()).arg(target->width()).arg(target->height())
                        .arg(target->isVisible()).arg(target->isEnabled())));
    const auto point = target->mapToScene(QPointF(target->width() / 2, target->height() / 2));
    if (dispatchedAt) *dispatchedAt = point;
    QTest::mouseClick(window, Qt::LeftButton, {}, point.toPoint());
}

static void click(QQuickWindow *window, QQuickItem *target, QPointF *dispatchedAt = nullptr)
{
    const QPointer<QQuickItem> guard(target);
    QVERIFY(guard);
    QTest::qWait(50);
    QVERIFY2(guard, "The click target disappeared during the readiness wait");
    clickReadyItem(window, guard.data(), dispatchedAt);
}

static void clickCurrentItem(QQuickWindow *window, const QString &name)
{
    // A sidebar refresh may recreate the delegate while events are processed.
    // Resolve its logical identity only after the readiness wait has finished.
    QTest::qWait(50);
    clickReadyItem(window, item(window->contentItem(), name));
}

static int itemCountWithPrefix(QQuickItem *root, const QString &prefix)
{
    int count = root->objectName().startsWith(prefix);
    for (auto *child : root->childItems()) count += itemCountWithPrefix(child, prefix);
    return count;
}

static bool hasVisibleText(QQuickItem *root, const QString &text)
{
    if (root->isVisible() && root->property("text").toString() == text) return true;
    for (auto *child : root->childItems())
        if (hasVisibleText(child, text)) return true;
    return false;
}

// #62: re-read the persisted window state (window/x|y|width|height) straight
// from the settings file; the debounced saver syncs there.
static QRect savedWindowBounds(const QString &path)
{
    const QSettings saved(path, QSettings::IniFormat);
    return QRect(saved.value("window/x").toInt(), saved.value("window/y").toInt(),
        saved.value("window/width").toInt(), saved.value("window/height").toInt());
}

static QQuickItem *fileEntry(QQuickItem *root, const QUrl &url)
{
    if (root->isVisible() && root->property("fileUrl").toUrl() == url) return root;
    for (auto *child : root->childItems())
        if (auto *found = fileEntry(child, url)) return found;
    return nullptr;
}

static QQuickItem *fileEntry(const QUrl &url)
{
    for (auto *candidate : QGuiApplication::allWindows())
        if (auto *window = qobject_cast<QQuickWindow *>(candidate))
            if (auto *found = fileEntry(window->contentItem(), url)) return found;
    return nullptr;
}

static QQuickItem *visibleItem(QQuickItem *root, const QString &name)
{
    if (root->isVisible() && root->objectName() == name) return root;
    for (auto *child : root->childItems())
        if (auto *found = visibleItem(child, name)) return found;
    return nullptr;
}

