// Account controls remain visible QQuickItems when the scroll viewport clips
// them. Bring the physical click point inside the viewport and wait for paint.
static void clickAccountMenuControl(QQuickWindow *window, QQuickItem *target)
{
    auto *scroll = visibleItem(window->contentItem(), "accountMenuScroll");
    QVERIFY(scroll && target);
    QSignalSpy painted(window, &QQuickWindow::frameSwapped);
    window->update();
    QTRY_VERIFY([&] {
        if (!target->isEnabled() || !target->isVisible())
            return false;
        const auto center = target->mapToItem(scroll, QPointF(target->width() / 2, target->height() / 2));
        if (!scroll->contains(center)) {
            const qreal top = scroll->property("contentY").toReal();
            const qreal bottom = std::max<qreal>(0, scroll->property("contentHeight").toReal() - scroll->height());
            const qreal next = std::clamp(top + center.y() - scroll->height() / 2, 0.0, bottom);
            if (qAbs(next - top) > 0.5) {
                scroll->setProperty("contentY", next);
                painted.clear();
                window->update();
            }
            return false;
        }
        return !painted.isEmpty();
    }());
    clickReadyItem(window, target);
}

static void checkSidebarCardBelowExpandedActivity(QQuickWindow *window, const QString &cardName)
{
    auto *root = window->contentItem();
    clickCurrentItem(window, "activityExpandButton");
    QTRY_VERIFY(visibleItem(root, "activityHeader"));
    auto *panel = visibleItem(root, "sidebarActivityPanel"); QVERIFY(panel);
    auto *card = visibleItem(root, cardName); QVERIFY(card);
    QTRY_VERIFY(panel->height() > 32);
    const auto panelBounds = panel->mapRectToItem(root, QRectF(QPointF{}, panel->size()));
    const auto cardBounds = card->mapRectToItem(root, QRectF(QPointF{}, card->size()));
    QVERIFY2(!cardBounds.intersects(panelBounds) && cardBounds.top() >= panelBounds.bottom(),
        qPrintable(QStringLiteral("card top %1, expanded Activity bottom %2")
            .arg(cardBounds.top()).arg(panelBounds.bottom())));
}

// Issue #420: QtTest warns on any mouse event outside the window and window
// warnings fail cases, so a click on a control inside a scrolling page body
// must be gated on a real viewport reachability check. True when the item's
// whole bounding box maps inside the window (top-left scene origin plus
// size within the window extent).
static bool itemInsideWindow(QQuickWindow *window, QQuickItem *item)
{
    if (!item) return false;
    const QPointF top = item->mapToScene(QPointF(0, 0));
    return top.x() >= 0.0 && top.y() >= 0.0
        && top.x() + item->width() <= window->width()
        && top.y() + item->height() <= window->height();
}

// Issue #216: a vote (or add-option) response re-projects the row through
// replaceMessages, which rebuilds the option Repeater inside the reused row
// delegate. Qt's async incubation of that rebuild can leave a dying delegate
// on the visual children list (parentItem intact, raw visible flags live)
// with its QObject parent already cleared and the cached effective-visibility
// flag stale, while the fresh delegate incubates. Plain visibleItem searches
// the cached effective flag, which lags far beyond a QTRY window in the
// headless runner, and can also stop on the frozen dying duplicate. These
// poll helpers check the raw visible flags along the visual chain and return
// the last (freshest) match: the deterministic signal that the live UI logic
// flipped the element on.
static bool pollRawChainVisible(QQuickItem *item)
{
    for (auto *a = item; a; a = a->parentItem())
        if (!a->property("visible").toBool()) return false;
    return true;
}
static void collectPollVisible(QQuickItem *root, const QString &name, QList<QQuickItem *> &out)
{
    if (root->objectName() == name && pollRawChainVisible(root)) out.append(root);
    for (auto *child : root->childItems()) collectPollVisible(child, name, out);
}
// The fresh delegate is appended to its parent's children after the dying
// duplicate that replaceMessages left behind, so the last raw-visible match
// is the live one; value reads must not stop on the frozen dying item.
static QQuickItem *pollVisibleItem(QQuickItem *root, const QString &name)
{
    QList<QQuickItem *> matches;
    collectPollVisible(root, name, matches);
    return matches.isEmpty() ? nullptr : matches.last();
}
static bool pollItemEnabled(QQuickItem *root, const QString &name)
{
    auto *item = pollVisibleItem(root, name);
    return item && item->isEnabled();
}
static bool pollItemDisabled(QQuickItem *root, const QString &name)
{
    auto *item = pollVisibleItem(root, name);
    return item && !item->isEnabled();
}

