static QByteArray mediaViewerGarbageVideoBytes()
{
    return QByteArray("NOT-A-DECODABLE-VIDEO-FILE-FOR-DISPLAY-ERROR-TESTING");
}

// A markdown row carrying one standalone video reference (issue #203).
static QJsonObject mediaViewerVideoRow(const QString &uuid, const QString &fileUuid, qint64 byteSize)
{
    const auto urn = QStringLiteral("urn:video:%1?name=clip.mp4&content_type=video%2Fmp4&size=%2")
        .arg(fileUuid, QString::number(byteSize));
    auto row = message(QStringLiteral("Look\n\n![clip.mp4](%1)").arg(urn), uuid);
    row["user_uuid"] = userId;
    row["author_uuid"] = channelPeer; row["is_own"] = false;
    row["pinned"] = false; row["reactions"] = QJsonObject{};
    row["reaction_users"] = QJsonObject{}; row["updated_at"] = row.value("created_at");
    return row;
}

// A markdown row carrying one HEIC image reference (issue #638). The urn
// mirrors what the composer now produces for HEIC: urnType image WITHOUT
// w/h (FileMetadata::urnKind forces image and skips the dimension probe),
// so the surfaces must resolve the preview from the container, not metadata.
static QJsonObject mediaViewerHeicRow(const QString &uuid, const QString &fileUuid,
                                      qint64 byteSize, const QString &name = QStringLiteral("trip.heic"))
{
    const auto urn = QStringLiteral("urn:image:%1?name=%2&content_type=image%2Fheic&size=%3")
        .arg(fileUuid, name, QString::number(byteSize));
    auto row = message(QStringLiteral("Look\n\n![%1](%2)").arg(name, urn), uuid);
    row["user_uuid"] = userId;
    row["author_uuid"] = channelPeer; row["is_own"] = false;
    row["pinned"] = false; row["reactions"] = QJsonObject{};
    row["reaction_users"] = QJsonObject{}; row["updated_at"] = row.value("created_at");
    return row;
}

// Bug #690: sample the HEIC bubble's solid fill against its CURRENT geometry.
// A hint-less HEIC keeps the 240x180 reservation until the decode publishes
// its size, so the bubble collapses when a slow preview finally lands; a rect
// captured while the reservation was expanded can sit permanently outside the
// painted image (the deterministic pixel FAIL under CI parallel load). Every
// pass of a pixel wait must re-read the live geometry instead.
static bool heicBubbleShowsSolidFill(QQuickWindow *window, QQuickItem *bubble,
                                     const QColor &expected)
{
    const QRectF imageRect(bubble->mapToScene(QPointF{}), bubble->size());
    if (imageRect.width() < 40 || imageRect.height() < 24) return false;
    const auto pixels = window->grabWindow();
    if (pixels.isNull() || !pixels.rect().contains(imageRect.toAlignedRect())) return false;
    const auto close = [&](const QColor &a) {
        return qAbs(a.red() - expected.red()) <= 12 && qAbs(a.green() - expected.green()) <= 12
            && qAbs(a.blue() - expected.blue()) <= 12;
    };
    const QPointF points[] = {QPointF(.25, .25), QPointF(.5, .5), QPointF(.75, .5), QPointF(.5, .75)};
    for (const auto &point : points) {
        const auto at = imageRect.topLeft() + QPointF(imageRect.width() * point.x(),
                                                      imageRect.height() * point.y());
        if (!close(pixels.pixelColor(at.toPoint()))) return false;
    }
    return true;
}

// ---- Poll bubble fixtures (issue #216, docs/NATIVE_DESKTOP_POLLS_BUBBLE.md) ----
// Wire-shaped fixtures mirror the reference poll DTO at workspace_ui
// 230e02b8b0273dee556a406746d122180a68b3e7 (same uuids as the controller-side
// #214 fixtures). The scenario object plays the server: it applies vote and
// add-poll-option invokes and can defer one response so in-flight states are
// reproduced without sleeps.
static const QString pollBubbleQuestionOne = "a1a1a1a1-1111-4111-8111-111111111111";
static const QString pollBubbleQuestionTwo = "b2b2b2b2-2222-4222-8222-222222222222";
static const QString pollBubbleOptionOne = "c3c3c3c3-3333-4333-8333-333333333333";
static const QString pollBubbleOptionTwo = "d4d4d4d4-4444-4444-8444-444444444444";
static const QString pollBubbleOptionThree = "e5e5e5e5-5555-4555-8555-555555555555";
static const QString pollBubbleOptionFour = "f6f6f6f6-6666-4666-8666-666666666666";

class WindowPollFixture {
public:
    MockServer server;
    QString messageUuid = QStringLiteral("8d000000-0000-4000-8000-000000000001");
    QString messageUuidTwo = QStringLiteral("8d000000-0000-4000-8000-000000000002");
    QString streamSource = "native";
    bool streamEncrypted = false;
    bool ownPoll = false;
    int closePosts = 0, managementStatus = 200;
    bool holdManagement = false;
    QJsonObject lastSettings;
    std::function<void()> releaseManagement;
    bool secondPollOnPage = false;
    QJsonArray replies;
    // Poll config (reference defaults per the polls contract).
    bool multipleAnswers = true;
    bool anonymous = false;
    bool allowRevote = false;
    QString resultsVisibility = QStringLiteral("after_vote");
    bool allowAddingOptions = true;
    bool secondQuestion = false;
    QString closesAt = QStringLiteral("2026-12-12T09:00:00Z");
    QStringList correctOptionUuids;
    // Mutable poll state (server side).
    qint64 revision = 5;
    bool closed = false;
    QString closedAt;
    qint64 voterCount = 3;
    QJsonArray myVotes;
    // Question counts (3 voters): optionOne=1 optionTwo=2; question 2 mirrors.
    qint64 countOne = 1, countTwo = 2, countThree = 3, countFour = 0;
    int votePosts = 0, addOptionPosts = 0, settingsPosts = 0;
    QJsonObject lastVoteBody, lastAddOptionBody;
    QStringList addOptionUuids;
    int voteStatus = 200, addOptionStatus = 200;
    bool holdVote = false, holdAddOption = false;
    std::function<void()> releaseVote, releaseAddOption;
    // Options added through the add_poll_option invoke (server side): client
    // uuid + text appended to question 1; a replay of the same uuid is
    // idempotent (the reference 200s with the unchanged message).
    QList<QPair<QString, QString>> addedOptions;
    QJsonObject firstQuestionPreviews, extraOptionCounts;
    std::function<Response(const Request &)> voters;

    QJsonObject payload(const QString &questionText = QStringLiteral("Which day?")) const
    {
        QJsonObject question{{"uuid", pollBubbleQuestionOne}, {"text", questionText},
            {"options", QJsonArray{
                QJsonObject{{"uuid", pollBubbleOptionOne}, {"text", QStringLiteral("Monday")}},
                QJsonObject{{"uuid", pollBubbleOptionTwo}, {"text", QStringLiteral("Tuesday")}}}}};
        if (!correctOptionUuids.isEmpty())
            question["correct_option_uuids"] = QJsonArray::fromStringList(correctOptionUuids);
        auto options = question.value("options").toArray();
        for (const auto &added : addedOptions)
            options.append(QJsonObject{{"uuid", added.first}, {"text", added.second}});
        question["options"] = options;
        QJsonArray questions{question};
        if (secondQuestion)
            questions.append(QJsonObject{{"uuid", pollBubbleQuestionTwo},
                {"text", QStringLiteral("Where?")},
                {"options", QJsonArray{
                    QJsonObject{{"uuid", pollBubbleOptionThree}, {"text", QStringLiteral("Office")}},
                    QJsonObject{{"uuid", pollBubbleOptionFour}, {"text", QStringLiteral("Cafe")}}}}});
        return {{"kind", QStringLiteral("poll")},
            {"questions", questions},
            {"multiple_answers", multipleAnswers},
            {"is_anonymous", anonymous},
            {"allow_revote", allowRevote},
            {"results_visibility", resultsVisibility},
            {"allow_adding_options", allowAddingOptions},
            {"closes_at", closesAt.isEmpty() ? QJsonValue(QJsonValue::Null) : QJsonValue(closesAt)},
            {"closed_at", closedAt.isEmpty() ? QJsonValue(QJsonValue::Null) : QJsonValue(closedAt)}};
    }
    QJsonObject state() const
    {
        auto firstCounts = extraOptionCounts;
        firstCounts[pollBubbleOptionOne] = countOne;
        firstCounts[pollBubbleOptionTwo] = countTwo;
        return {{"revision", revision}, {"is_closed", closed}, {"voter_count", voterCount},
            {"questions", QJsonArray{
                QJsonObject{{"question_uuid", pollBubbleQuestionOne}, {"voter_count", 3},
                    {"option_voter_previews", firstQuestionPreviews},
                    {"option_counts", firstCounts}},
                QJsonObject{{"question_uuid", pollBubbleQuestionTwo}, {"voter_count", 3},
                    {"option_counts", QJsonObject{{pollBubbleOptionThree, countThree},
                        {pollBubbleOptionFour, countFour}}}}}},
            {"my_votes", myVotes}};
    }
    QJsonObject row(const QString &id, const QString &questionText) const
    {
        return {{"uuid", id}, {"project_id", projectId}, {"stream_uuid", streamId},
            {"topic_uuid", topicId}, {"author_uuid", ownPoll ? userId : channelPeer}, {"is_own", ownPoll},
            {"read", true}, {"starred", false},
            {"created_at", QStringLiteral("2026-01-02T10:00:30.000Z")},
            {"payload", payload(questionText)}, {"poll_state", state()}};
    }
    QJsonObject row() const { return row(messageUuid, QStringLiteral("Which day?")); }

    void applyVote(const QJsonObject &body)
    {
        const auto question = body.value("question_uuid").toString();
        const auto option = body.value("option_uuid").toString();
        const bool selected = body.value("selected").toBool();
        QJsonArray votes;
        for (const auto &value : myVotes) {
            auto vote = value.toObject();
            if (vote.value("question_uuid").toString() == question) {
                auto options = vote.value("option_uuids").toArray();
                QStringList picked;
                for (const auto &entry : options) picked.append(entry.toString());
                if (selected && !multipleAnswers) picked.clear();
                if (selected && !picked.contains(option)) picked.append(option);
                if (!selected) picked.removeAll(option);
                if (picked.isEmpty()) continue;
                vote["option_uuids"] = QJsonArray::fromStringList(picked);
            }
            votes.append(vote);
        }
        const bool known = std::any_of(votes.cbegin(), votes.cend(), [&](const QJsonValue &value) {
            return value.toObject().value("question_uuid").toString() == question;
        });
        if (selected && !known)
            votes.append(QJsonObject{{"question_uuid", question},
                {"option_uuids", QJsonArray{option}}});
        myVotes = votes;
        if (option == pollBubbleOptionOne) countOne += selected ? 1 : -1;
        if (option == pollBubbleOptionTwo) countTwo += selected ? 1 : -1;
        if (option == pollBubbleOptionThree) countThree += selected ? 1 : -1;
        if (option == pollBubbleOptionFour) countFour += selected ? 1 : -1;
        ++revision;
    }

    void applyAddOption(const QJsonObject &body)
    {
        // The reference only ever adds to one question per invoke; the
        // fixture mirrors that with the first question receiving the option.
        const auto option = body.value("option").toObject();
        const auto uuid = option.value("uuid").toString();
        const auto text = option.value("text").toString();
        if (uuid.isEmpty() || text.isEmpty()) return;
        const bool replay = std::any_of(addedOptions.cbegin(), addedOptions.cend(),
            [&](const QPair<QString, QString> &pair) { return pair.first == uuid; });
        if (replay) return;
        addedOptions.append({uuid, text});
        ++revision;
    }

    WindowPollFixture()
    {
        server.handler = [this](const Request &request) -> Response {
            const auto path = request.target.path();
            if (path.endsWith("/poll_voters/") && voters) return voters(request);
            const auto actions = "/api/workspace/v1/messenger/messages/" + messageUuid + "/actions/";
            if (path == actions + "vote/invoke") {
                const auto body = request.body;
                ++votePosts;
                lastVoteBody = body;
                if (voteStatus == 200) applyVote(body);
                Response response{row(), voteStatus};
                if (holdVote) {
                    holdVote = false;
                    response.defer = [this](std::function<void()> send) {
                        releaseVote = std::move(send);
                    };
                }
                return response;
            }
            if (path == actions + "add_poll_option/invoke") {
                ++addOptionPosts;
                lastAddOptionBody = request.body;
                addOptionUuids.append(request.body.value("option").toObject()
                    .value("uuid").toString());
                if (addOptionStatus == 200) applyAddOption(request.body);
                Response response{row(), addOptionStatus};
                if (holdAddOption) {
                    holdAddOption = false;
                    response.defer = [this](std::function<void()> send) {
                        releaseAddOption = std::move(send);
                    };
                }
                return response;
            }
            if (path == actions + "update_settings/invoke" || path == actions + "close_poll/invoke") {
                if (path == actions + "close_poll/invoke") {
                    ++closePosts;
                    if (managementStatus == 200) closed = true;
                } else {
                    ++settingsPosts;
                    lastSettings = request.body.value("settings").toObject();
                    if (managementStatus == 200) {
                        allowAddingOptions = lastSettings.value("allow_adding_options").toBool();
                        closesAt = lastSettings.value("closes_at").toString();
                    }
                }
                if (managementStatus == 200) ++revision;
                Response response{row(), managementStatus};
                if (holdManagement) {
                    holdManagement = false;
                    response.defer = [this](std::function<void()> send) { releaseManagement = std::move(send); };
                }
                return response;
            }
            if (path.endsWith("/streams/") && request.method == "GET") {
                auto stream = windowChannel(streamId, QStringLiteral("Product team"));
                stream["source_name"] = streamSource;
                stream["encryption"] = streamEncrypted;
                return {QJsonArray{stream}};
            }
            if (path == "/api/workspace/v1/messenger/streams/" + streamId) {
                auto stream = windowChannel(streamId, QStringLiteral("Product team"));
                stream["source_name"] = streamSource;
                stream["encryption"] = streamEncrypted;
                return {stream};
            }
            if (path.endsWith("/stream_topics/"))
                return {QJsonArray{windowChannelTopic(topicId, streamId, QStringLiteral("General"))}};
            if (path == "/api/workspace/v1/messenger/stream_topics/" + topicId)
                return {windowChannelTopic(topicId, streamId, QStringLiteral("General"))};
            if (path.endsWith("/users/"))
                return {QJsonArray{QJsonObject{{"uuid", userId}, {"username", QStringLiteral("cassi")}}}};
            if (path.endsWith("/messages/") && request.method == "GET") {
                QJsonArray rows{row()};
                for (const auto &reply : replies) rows.append(reply);
                if (secondPollOnPage)
                    rows.append(row(messageUuidTwo, QStringLiteral("Where?")));
                return {rows};
            }
            return sessionResponse(request);
        };
    }
    ~WindowPollFixture()
    {
        if (releaseVote) releaseVote();
        if (releaseAddOption) releaseAddOption();
        if (releaseManagement) releaseManagement();
    }
};

static QString pollItemText(QQuickItem *root, const QString &name)
{
    auto *target = pollVisibleItem(root, name);
    return target ? target->property("text").toString() : QString();
}

static bool pollItemExists(QQuickItem *root, const QString &name)
{
    auto *target = pollVisibleItem(root, name);
    return target != nullptr;
}

static QQuickItem *avatarProbeCircle(QQuickItem *root, qreal diameter)
{
    if (!root || !root->isVisible()) return nullptr;
    if (root->size() == QSizeF(diameter, diameter)
        && root->property("radius").toReal() == diameter / 2) return root;
    for (auto *child : root->childItems())
        if (auto *found = avatarProbeCircle(child, diameter)) return found;
    return nullptr;
}

static QQuickItem *avatarProbeReadyImage(QQuickItem *root)
{
    if (!root || !root->isVisible()) return nullptr;
    const auto source = root->property("source").toUrl();
    // Image.status is the public QML enum: Null=0, Ready=1, Loading=2, Error=3.
    if (source.scheme() == "image" && source.host() == "avatars"
        && root->property("status").toInt() == 1) return root;
    for (auto *child : root->childItems())
        if (auto *found = avatarProbeReadyImage(child)) return found;
    return nullptr;
}

static bool avatarProbeHasVisibleLock(QQuickItem *root)
{
    if (!root || !root->isVisible()) return false;
    if (root->property("asset").toString() == "chat_lock.svg") return true;
    for (auto *child : root->childItems()) if (avatarProbeHasVisibleLock(child)) return true;
    return false;
}

static bool avatarProbeMatchesPixels(QQuickWindow *window, QQuickItem *face, bool peer)
{
    if (!window || !face || !face->isVisible()) return false;
    const auto image = window->grabWindow();
    if (image.isNull()) return false;
    const auto dpr = window->devicePixelRatio();
    const auto sample = [&](const QPointF &local) -> QColor {
        const auto scene = face->mapToScene(local) * dpr;
        const QPoint pixel(qFloor(scene.x()), qFloor(scene.y()));
        return image.rect().contains(pixel) ? image.pixelColor(pixel) : QColor{};
    };
    const auto close = [](const QColor &a, const QColor &b) {
        return a.isValid() && b.isValid() && qAbs(a.red() - b.red()) <= 3
            && qAbs(a.green() - b.green()) <= 3 && qAbs(a.blue() - b.blue()) <= 3;
    };
    const QColor red(228,31,45), green(21,177,86), blue(35,103,232), gold(243,183,24);
    const QVector<QColor> colors = peer ? QVector<QColor>{blue,gold,red,green}
                                       : QVector<QColor>{red,green,blue,gold};
    const QSizeF inner(face->width()-2, face->height()-2);
    const QVector<QPointF> locations{{.30,.28},{.70,.28},{.30,.72},{.70,.72},{.12,.28},{.88,.28}};
    const int expected[]{0,1,2,3,0,1};
    for (qsizetype i=0; i<locations.size(); ++i) {
        const QPointF local(1 + locations[i].x()*inner.width(), 1 + locations[i].y()*inner.height());
        if (!close(sample(local), colors[expected[i]])) return false;
    }
    // These corners are outside the circle. Compare with adjacent real parent
    // background, not a guessed theme/hover surface. Square image leakage fails.
    return close(sample(QPointF(2,2)), sample(QPointF(-2,2)));
}

static bool presenceProbeMatchesPixels(QQuickWindow *window, QQuickItem *badge,
                                      const QColor &fill, const QColor &ring)
{
    if (!window || !badge || !badge->isVisible()) return false;
    const auto pixels=window->grabWindow();
    if(pixels.isNull()) return false;
    const auto sample=[&](QPointF local) {
        const auto point=badge->mapToScene(local)*window->devicePixelRatio();
        const QPoint pixel(qFloor(point.x()),qFloor(point.y()));
        return pixels.rect().contains(pixel)?pixels.pixelColor(pixel):QColor{};
    };
    const auto close=[](const QColor &actual,const QColor &expected) {
        return actual.isValid()&&qAbs(actual.red()-expected.red())<=3
            &&qAbs(actual.green()-expected.green())<=3&&qAbs(actual.blue()-expected.blue())<=3;
    };
    // Stable interiors only; no cross-renderer antialiasing or exact edge claim.
    return close(sample({6,6}),fill)&&close(sample({11,6}),ring);
}


