    // Issue #38: the /feed route opens the project feed page, rows render with
    // the measured reference layout, top pagination rides X-Pagination-Marker,
    // open-in-chat reuses the topic navigation path and the forward button is
    // gated until the forward flow ships. Geometry contract: workspace_ui
    // 61dacef78dab2f5d0be76f283bebf49fe29b84af feed-page.ui.tsx.
    void feedPageRouteOpensPageAndRendersRows()
    {
        WindowFeedFixture fixture;
        for (int i = 1; i <= 24; ++i) fixture.rows.insert(i, fixture.one(i));
        const QString sourceId = fixture.one(12).value("uuid").toString();
        QTemporaryDir directory; QVERIFY(directory.isValid());
        NativePreferences preferences(directory.filePath("p.ini"));
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard) closeIncubatedTestWindow(engine, guard.data());
        });
        QVERIFY(QTest::qWaitForWindowExposed(window)); window->requestActivate();
        QVERIFY(startComposerEmojiFixture(fixture, controller, session));
        const auto view = [&](const QString &name) { return visibleItem(window->contentItem(), name); };
        QTRY_VERIFY(!controller.messages().isEmpty());
        const auto chatId = controller.messages().first().toMap().value("id").toString();
        QVERIFY(!chatId.isEmpty() && chatId != sourceId);
        QVERIFY(QMetaObject::invokeMethod(window, "toggleMessageSelection", Q_ARG(QVariant, chatId)));
        QCOMPARE(window->property("messageSelectionCount").toInt(), 1);
        // The feed route is the entry surface: the reference keeps the rail
        // entry hidden (sidebar.lib.ts:80-98), so parity means the route only.
        const auto link = QString("ew://open/org/%1/project/%2/feed")
            .arg(workspace::orgRouteIdFromOrigin(fixture.server.origin()), projectId);
        controller.openMessageLink(link);
        QTRY_VERIFY(controller.feedVisible());
        QVERIFY(view("nativeFeedPage"));
        QVERIFY(hasVisibleText(window->contentItem(), "All messages"));
        QTRY_VERIFY_WITH_TIMEOUT(view("feed-row-" + sourceId)
            && view("feed-row-" + fixture.one(3).value("uuid").toString()), 5000);
        // Context pill: "${stream name} \u00b7 ${topic name}" with the scene names.
        auto *context = view("feed-context-" + sourceId); QVERIFY(context);
        QCOMPARE(context->property("text").toString(), QString("Product team \u00b7 Planning"));
        auto *sender = view("feed-sender-" + sourceId); QVERIFY(sender);
        QCOMPARE(sender->property("text").toString(), QString("Alice"));
        QVERIFY(view("feed-summary-" + sourceId));
        // Row card geometry: rounded-xl (12 px) with a border (feed-page.ui.tsx:363-370).
        auto *row = view("feed-row-" + sourceId);
        QCOMPARE(row->property("radius").toInt(), 12);
        auto *rowBorder = qvariant_cast<QObject *>(row->property("border")); QVERIFY(rowBorder);
        QCOMPARE(rowBorder->property("width").toInt(), 1);
        auto *forward = view("feed-forward-" + sourceId); QVERIFY(forward);
        auto *dialog = window->findChild<QObject *>("forwardDialog"); QVERIFY(dialog);
        auto *list = view("feedList"); QVERIFY(list);
        // The feed positions the initial page after delegates have been measured.
        // Record the reading position once that startup movement has finished.
        QTRY_VERIFY(!view("nativeFeedPage")->property("anchorRunning").toBool());
        QTRY_VERIFY(list->property("contentHeight").toReal() > list->height() * 2);
        const qreal position = qRound(row->y()) - 24;
        QVERIFY(position > 0);
        list->setProperty("contentY", position);
        QTRY_COMPARE(list->property("contentY").toReal(), position);
        const auto messagePosts = [&] {
            return std::count_if(fixture.server.requests.cbegin(), fixture.server.requests.cend(),
                [](const Request &request) { return request.method == "POST" && request.target.path().endsWith("/messages/"); });
        };
        const auto initialPosts = messagePosts();
        for (const bool keyboard : {false, true}) {
            if (keyboard) {
                forward->forceActiveFocus(Qt::TabFocusReason);
                QVERIFY(forward->hasActiveFocus());
                QTest::keyClick(window, Qt::Key_Space);
            } else {
                click(window, forward);
            }
            QTRY_VERIFY(dialog->property("opened").toBool());
            QCOMPARE(dialog->property("sourceIds").value<QJSValue>().toVariant().toStringList(),
                QStringList{sourceId});
            QVERIFY(controller.feedVisible());
            QCOMPARE(messagePosts(), initialPosts);
            click(window, view("forwardCancelButton"));
            QTRY_VERIFY(!dialog->property("visible").toBool());
            QVERIFY(controller.feedVisible());
            QCOMPARE(list->property("contentY").toReal(), position);
            QCOMPARE(window->property("messageSelectionCount").toInt(), 1);
            QCOMPARE(messagePosts(), initialPosts);
        }
        // Open-in-chat reuses the topic navigation path and unmounts the page.
        click(window, view("feed-open-" + sourceId));
        QTRY_VERIFY_WITH_TIMEOUT(!controller.feedVisible()
            && controller.selectedTopic() == secondTopicId, 5000);
        // Reopening and closing via the page chrome works.
        controller.showFeed();
        QTRY_VERIFY(controller.feedVisible() && view("nativeFeedPage"));
        click(window, view("feedCloseButton"));
        QVERIFY(!controller.feedVisible());
    }

    // Issue #355: the Feed page is a content page. While it is open the
    // conversation header, message list and composer must all be hidden and
    // the Feed must own the central content area, both at a normal window width
    // and at the minimum supported one (Main.qml minimumWidth: 700). Opening a
    // Feed row returns the normal conversation layout.
    void feedPageHidesConversationAndOwnsContentWidth()
    {
        WindowFeedFixture fixture;
        fixture.rows = {{1, fixture.one(1)}, {2, fixture.one(2)}, {3, fixture.one(3)}};
        const QString firstId = fixture.one(1).value("uuid").toString();
        QTemporaryDir directory; QVERIFY(directory.isValid());
        NativePreferences preferences(directory.filePath("p.ini"));
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard) closeIncubatedTestWindow(engine, guard.data());
        });
        window->resize(1440, 900);
        QVERIFY(QTest::qWaitForWindowExposed(window)); window->requestActivate();
        QVERIFY(startComposerEmojiFixture(fixture, controller, session));
        const auto view = [&](const QString &name) { return visibleItem(window->contentItem(), name); };
        // Hidden panels must stay findable, so search by object name only.
        std::function<QQuickItem *(QQuickItem *, const QString &)> walk
            = [&](QQuickItem *root, const QString &name) -> QQuickItem * {
                if (root->objectName() == name) return root;
                for (auto *child : root->childItems())
                    if (auto *found = walk(child, name)) return found;
                return nullptr;
            };
        const auto named = [&](const QString &name) { return walk(window->contentItem(), name); };
        const QStringList panels{"conversationPanel", "conversationHeader", "messageList",
            "messageComposer"};
        // A normal conversation keeps all three surfaces on screen.
        for (const auto &name : panels) {
            auto *item = named(name); QVERIFY2(item, qPrintable(name));
            QVERIFY2(item->isVisible(), qPrintable(name));
            QVERIFY2(item->width() > 0, qPrintable(name));
        }
        auto *panel = named("conversationPanel"); QVERIFY(panel);
        auto *workspace = panel->parentItem(); QVERIFY(workspace);
        const auto contentWidthBefore = panel->width();
        const auto contentLeftBefore = panel->mapToItem(workspace, QPointF(0, 0)).x();
        QVERIFY(contentWidthBefore > 0);
        const auto link = QString("ew://open/org/%1/project/%2/feed")
            .arg(workspace::orgRouteIdFromOrigin(fixture.server.origin()), projectId);
        controller.openMessageLink(link);
        QTRY_VERIFY(controller.feedVisible());
        QTRY_VERIFY_WITH_TIMEOUT(view("feed-row-" + firstId) != nullptr, 5000);
        // Feed owns the central content area: all three conversation surfaces
        // are hidden (a skipped Layout child keeps its last width, so the
        // visible-footprint contract is proven by the Feed geometry below),
        // the Feed fills the space the conversation used to have, and it starts
        // at the same left edge - no second message surface beside it.
        const auto assertFeedOwnsContentArea = [&](qreal contentWidth, qreal contentLeft,
                                                   qreal minimumFeedWidth) {
            for (const auto &name : panels) {
                auto *hidden = named(name); QVERIFY2(hidden, qPrintable(name));
                QVERIFY2(!hidden->isVisible(),
                    qPrintable(name + QStringLiteral(" stayed visible while Feed is open")));
            }
            auto *feed = named("nativeFeedPage"); QVERIFY(feed);
            QVERIFY2(feed->isVisible(), "the Feed page is not visible");
            QVERIFY2(workspace->width() > 0, "the workspace has no width");
            QVERIFY2(feed->width() >= contentWidth - 8,
                qPrintable(QStringLiteral("feed %1 vs conversation %2")
                    .arg(feed->width()).arg(contentWidth)));
            QVERIFY2(feed->width() >= minimumFeedWidth,
                qPrintable(QStringLiteral("feed width %1").arg(feed->width())));
            const auto feedLeft = feed->mapToItem(workspace, QPointF(0, 0)).x();
            QVERIFY2(qAbs(feedLeft - contentLeft) < 8,
                qPrintable(QStringLiteral("feed left %1 vs conversation left %2")
                    .arg(feedLeft).arg(contentLeft)));
        };
        assertFeedOwnsContentArea(contentWidthBefore, contentLeftBefore, 600);
        // The same contract at the minimum supported window width: measure the
        // content area again with the conversation back on screen, then reopen.
        click(window, view("feedCloseButton"));
        QVERIFY(!controller.feedVisible());
        window->resize(700, 600);
        QTRY_COMPARE_WITH_TIMEOUT(window->width(), 700, 4000);
        QTRY_VERIFY_WITH_TIMEOUT(named("conversationPanel")->isVisible()
            && named("messageComposer")->isVisible(), 4000);
        const auto minWidth = named("conversationPanel")->width();
        const auto minLeft = named("conversationPanel")->mapToItem(workspace, QPointF(0, 0)).x();
        QVERIFY(minWidth > 0);
        controller.showFeed();
        QTRY_VERIFY_WITH_TIMEOUT(controller.feedVisible()
            && !named("conversationPanel")->isVisible(), 4000);
        assertFeedOwnsContentArea(minWidth, minLeft, 300);
        // Opening a Feed row returns the conversation layout (open-in-chat).
        window->resize(1440, 900);
        QTRY_COMPARE_WITH_TIMEOUT(window->width(), 1440, 4000);
        click(window, view("feed-open-" + firstId));
        QTRY_VERIFY_WITH_TIMEOUT(!controller.feedVisible()
            && controller.selectedTopic() == secondTopicId, 5000);
        for (const auto &name : panels) {
            auto *item = named(name); QVERIFY2(item, qPrintable(name));
            QVERIFY2(item->isVisible(), qPrintable(name));
            QVERIFY2(item->width() > 0, qPrintable(name));
        }
    }

    void feedPageTopPaginationAnchorsAndDoesNotDoubleRequest()
    {
        WindowFeedFixture fixture;
        for (int n = 1; n <= 60; ++n)
            fixture.rows.insert(n, fixture.one(n));
        fixture.gateMarker = true;
        QTemporaryDir directory; QVERIFY(directory.isValid());
        NativePreferences preferences(directory.filePath("p.ini"));
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard) closeIncubatedTestWindow(engine, guard.data());
        });
        QVERIFY(QTest::qWaitForWindowExposed(window)); window->requestActivate();
        QVERIFY(startComposerEmojiFixture(fixture, controller, session));
        const auto view = [&](const QString &name) { return visibleItem(window->contentItem(), name); };
        controller.showFeed();
        QTRY_VERIFY_WITH_TIMEOUT(controller.feedPage().value("rows").toList().size() == 50, 5000);
        auto *page = view("nativeFeedPage"); QVERIFY(page);
        auto *list = view("feedList"); QVERIFY(list);
        // Initial load anchors at the newest messages (feed-page.ui.test.tsx:534).
        const auto atBottom = [list] {
            return list->property("contentHeight").toReal()
                - list->property("contentY").toReal()
                - list->property("height").toReal() <= 1.0;
        };
        QTRY_VERIFY_WITH_TIMEOUT(!page->property("anchorRunning").toBool() && atBottom(), 5000);
        QVERIFY(!view("feedScrollToBottom")); // hidden within 80 px of bottom
        // Reaching the top fires exactly one marker request; the gated response
        // stays in flight while the user scrolls away and back: the armed flag
        // re-arms past 96 px but the in-flight request still blocks a second one.
        list->setProperty("contentY", 0.0);
        QTRY_VERIFY_WITH_TIMEOUT(!fixture.gates->empty(), 3000);
        list->setProperty("contentY", 400.0);
        QTRY_VERIFY_WITH_TIMEOUT(list->property("contentY").toReal() > 96.0, 2000);
        list->setProperty("contentY", 10.0);
        QTest::qWait(200);
        QCOMPARE(fixture.feedMarkerPages, 1); // never while in flight
        // The floating scroll-to-bottom button appeared while away from bottom.
        QVERIFY(view("feedScrollToBottom"));
        for (auto &release : *fixture.gates)
            release();
        fixture.gates->clear();
        QTRY_VERIFY_WITH_TIMEOUT(controller.feedPage().value("rows").toList().size() == 60, 5000);
        // The prepend restore keeps the visual position: contentY moved down by
        // the merged height instead of jumping to the top.
        QTRY_VERIFY_WITH_TIMEOUT(list->property("contentY").toReal() > 10.0, 3000);
        QCOMPARE(fixture.feedMarkerPages, 1);
        // Clicking the button returns to the bottom.
        auto *bottom = view("feedScrollToBottom"); QVERIFY(bottom);
        clickReadyItem(window, bottom);
        QTRY_VERIFY_WITH_TIMEOUT(atBottom(), 3000);
    }

