    // Issue #638 sec 4 (docs/NATIVE_DESKTOP_HEIC_PREVIEWS.md): a HEIC attachment
    // paints an inline decoded preview in the bubble, the viewer shows a decoded
    // PNG render (slot-<N>-heif.png) while the download keeps saving the
    // untouched ORIGINAL container bytes (reference: the authorized original is
    // the download artifact, the display blob is a display-only substitution).
    void heicImagePaintsBubbleViewerRenderAndDownloadSavesOriginal()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const QString fileA = QStringLiteral("9f000000-0000-4000-8000-00000000000a");
        const QString first = QStringLiteral("9e000000-0000-4000-8000-000000000001");
        const QByteArray heic = heicFixture();
        const QColor heicColor(0x46, 0x82, 0xb4); // fixture solid fill
        const auto closeColor = [&](const QColor &a) {
            return qAbs(a.red() - heicColor.red()) <= 12 && qAbs(a.green() - heicColor.green()) <= 12
                && qAbs(a.blue() - heicColor.blue()) <= 12;
        };
        WindowChannelFixture fixture;
        const auto fallback = fixture.server.handler;
        fixture.server.handler = [&](const Request &request) -> Response {
            const auto path = request.target.path();
            if (path.startsWith("/api/workspace/v1/messenger/files/" + fileA)) {
                if (path.endsWith("/actions/download")) {
                    Response result; result.rawBody = heic; result.rawContentType = "image/heic";
                    return result;
                }
                auto metadata = avatarProbeMetadata(fileA, heic);
                metadata["stream_uuid"] = streamId; metadata["name"] = "trip.heic";
                metadata["content_type"] = "image/heic";
                return Response{metadata};
            }
            if (path.endsWith("/messages/") && request.method == "GET") {
                ++fixture.historyGets;
                return Response{QJsonArray{mediaViewerHeicRow(first, fileA, heic.size())}};
            }
            return fallback(request);
        };
        ApiClient api(nullptr, true); Session session(&api); FileClient files(&api);
        MessageImages images(&api, &session, &files);
        NativeController controller(&api, &session); controller.useFiles(&files);
        NativePreferences preferences(directory.filePath("heic-preview.ini"));
        preferences.setLocale("en"); preferences.setMode("light");
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences, nullptr, nullptr, &images);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto closeBeforeEngine = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard && !closeIncubatedTestWindow(engine, guard.data()))
                QTest::qFail("HEIC preview window did not settle before engine teardown", __FILE__, __LINE__);
        });
        window->resize(1440, 900); QVERIFY(QTest::qWaitForWindowExposed(window));
        window->requestActivate(); QVERIFY(QTest::qWaitForWindowActive(window));
        session.login(fixture.server.origin(), "synthetic", "synthetic");
        QTRY_COMPARE(session.projects().size(), 1); session.selectProject(projectId);
        QTRY_COMPARE(controller.streams().size(), 1); QTRY_VERIFY(controller.channelMembersVerified());
        auto *content = window->contentItem();
        click(window, visibleItem(content, "stream-" + streamId));
        QTRY_COMPARE(controller.topics().size(), 1);
        click(window, visibleItem(content, "topic-" + topicId));
        QTRY_COMPARE(controller.selectedTopic(), topicId);
        QTRY_COMPARE(controller.messages().size(), 1);
        // 1. Bubble thumbnail: the ISO-BMFF bytes decode through libheif and
        // paint the fixture's solid fill inside the inline image bounds.
        // Bug #690: a hint-less HEIC holds the 240x180 reservation until the
        // decode publishes its size, so the bubble collapses when a slow
        // preview lands. Waiting on a rect captured before that collapse made
        // the pixel assertion race the paint - deterministic FAIL under CI
        // parallel load. Wait for the pipeline verdict event-driven (17 s
        // covers the production 15 s decode watchdog), then sample the live
        // geometry, which the paint must reach within a few render passes.
        auto *bubble = visibleItem(content, "inline-image-" + first); QVERIFY(bubble);
        QVERIFY(!bubble->property("failed").toBool());
        QTRY_VERIFY_WITH_TIMEOUT(([&] {
            return !bubble->property("imageUrl").toString().isEmpty()
                || bubble->property("failed").toBool();
        })(), 17000);
        QVERIFY2(!bubble->property("failed").toBool(), "HEIC preview decode failed");
        QTRY_VERIFY_WITH_TIMEOUT(heicBubbleShowsSolidFill(window, bubble, heicColor), 8000);
        // 2. Viewer: the slot stays loading through the decode and lands ready
        // on the decoded PNG render, not on the ISO-BMFF original.
        auto *viewer = controller.mediaViewer();
        clickActiveInlineImage(window, first);
        QTRY_VERIFY(viewer->open());
        QTRY_VERIFY_WITH_TIMEOUT(([&]{ return viewer->items().at(0).toMap().value("state").toString()
            == QStringLiteral("ready"); })(), 10000);
        const auto renderUrl = QUrl(viewer->items().at(0).toMap().value("url").toString());
        QVERIFY2(renderUrl.toString().endsWith(QStringLiteral("/slot-0-heif.png")),
            qPrintable(renderUrl.toString()));
        QVERIFY(!renderUrl.toLocalFile().endsWith(QStringLiteral(".heic")));
        const auto renderPath = renderUrl.toLocalFile();
        QVERIFY2(QFile::exists(renderPath), qPrintable(renderPath));
        const QImage render(renderPath);
        QVERIFY(!render.isNull());
        QCOMPARE(render.size(), QSize(48, 32));
        QVERIFY2(closeColor(render.pixelColor(24, 16)),
            qPrintable(render.pixelColor(24, 16).name()));
        // The viewer image materializes a render pass after the slot reports
        // ready under CI parallel load; visibleItem returns null in that
        // window and the old unguarded dereference segfaulted the group
        // (null this into QQuickItem::isVisible, Bug #684).
        QQuickItem *viewerImage = nullptr;
        QTRY_VERIFY_WITH_TIMEOUT(([&] {
            viewerImage = visibleItem(content, "mediaViewer-image");
            return viewerImage && viewerImage->isVisible();
        })(), 8000);
        // 3. Download saves the ORIGINAL container, never the render.
        auto *downloadButton = visibleItem(content, "mediaViewer-download"); QVERIFY(downloadButton);
        QVERIFY(downloadButton->property("enabled").toBool());
        auto *saveDialog = window->findChild<QObject *>("attachmentSaveDialog"); QVERIFY(saveDialog);
        click(window, downloadButton);
        QTRY_VERIFY_WITH_TIMEOUT(saveDialog->property("visible").toBool(), 4000);
        QVERIFY(saveDialog->setProperty("currentFolder", QUrl::fromLocalFile(directory.path())));
        QTRY_VERIFY_WITH_TIMEOUT(visibleItem("fileNameTextField"), 4000);
        auto *filename = visibleItem("fileNameTextField");
        click(filename->window(), filename);
        QTest::keySequence(filename->window(), QKeySequence::SelectAll);
        for (const auto character : QByteArray("original.heic"))
            QTest::keyClick(filename->window(), character);
        QCOMPARE(filename->property("text").toString(), QString("original.heic"));
        QTRY_VERIFY_WITH_TIMEOUT(dialogButton("Save"), 4000);
        auto *saveButton = dialogButton("Save");
        QSignalSpy saveAccepted(saveDialog, SIGNAL(accepted())); QVERIFY(saveAccepted.isValid());
        click(saveButton->window(), saveButton);
        QTRY_COMPARE_WITH_TIMEOUT(saveAccepted.size(), 1, 4000);
        const auto saved = QDir(directory.path()).filePath("original.heic");
        QTRY_VERIFY_WITH_TIMEOUT(QFile::exists(saved), 4000);
        QFile savedFile(saved); QVERIFY(savedFile.open(QIODevice::ReadOnly));
        QCOMPARE(savedFile.readAll(), heic); // byte-identical original, not the PNG render
        QTest::keyClick(window, Qt::Key_Escape);
        QTRY_VERIFY(!viewer->open());
    }

    // Bug #690 regression: a late-landing HEIC preview must still paint in
    // the bubble. The metadata fetch is deferred, so the bubble is first
    // observed at the expanded 240x180 reservation; when the preview lands,
    // the row collapses to the decoded 48x32 frame. The pixel wait must
    // follow the live geometry and the pipeline verdict - a rect captured
    // mid-reservation races the paint, which is how both #687 CI runs failed
    // this area deterministically (the reinstated stale-rect pattern turns
    // this case RED; see heicBubbleShowsSolidFill).
    void lateHeicDecodeCollapsesBubbleGeometryAndStillPaints()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const QString fileA = QStringLiteral("9f000000-0000-4000-8000-00000000000a");
        const QString first = QStringLiteral("9e000000-0000-4000-8000-000000000001");
        const QByteArray heic = heicFixture();
        const QColor heicColor(0x46, 0x82, 0xb4);
        WindowChannelFixture fixture;
        const auto fallback = fixture.server.handler;
        auto releaseMeta = std::make_shared<std::function<void()>>();
        auto metaArrived = std::make_shared<bool>(false);
        fixture.server.handler = [&](const Request &request) -> Response {
            const auto path = request.target.path();
            if (path.startsWith("/api/workspace/v1/messenger/files/" + fileA)) {
                if (path.endsWith("/actions/download")) {
                    Response result; result.rawBody = heic; result.rawContentType = "image/heic";
                    return result;
                }
                auto metadata = avatarProbeMetadata(fileA, heic);
                metadata["stream_uuid"] = streamId; metadata["name"] = "trip.heic";
                metadata["content_type"] = "image/heic";
                Response result{metadata};
                result.defer = [releaseMeta, metaArrived](std::function<void()> send) {
                    *releaseMeta = std::move(send); *metaArrived = true;
                };
                return result;
            }
            if (path.endsWith("/messages/") && request.method == "GET") {
                ++fixture.historyGets;
                return Response{QJsonArray{mediaViewerHeicRow(first, fileA, heic.size())}};
            }
            return fallback(request);
        };
        ApiClient api(nullptr, true); Session session(&api); FileClient files(&api);
        MessageImages images(&api, &session, &files);
        NativeController controller(&api, &session); controller.useFiles(&files);
        NativePreferences preferences(directory.filePath("heic-late.ini"));
        preferences.setLocale("en"); preferences.setMode("light");
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences, nullptr, nullptr, &images);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto closeBeforeEngine = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard && !closeIncubatedTestWindow(engine, guard.data()))
                QTest::qFail("Late HEIC window did not settle before engine teardown", __FILE__, __LINE__);
        });
        window->resize(1440, 900); QVERIFY(QTest::qWaitForWindowExposed(window));
        window->requestActivate(); QVERIFY(QTest::qWaitForWindowActive(window));
        session.login(fixture.server.origin(), "synthetic", "synthetic");
        QTRY_COMPARE(session.projects().size(), 1); session.selectProject(projectId);
        QTRY_COMPARE(controller.streams().size(), 1); QTRY_VERIFY(controller.channelMembersVerified());
        auto *content = window->contentItem();
        click(window, visibleItem(content, "stream-" + streamId));
        QTRY_COMPARE(controller.topics().size(), 1);
        click(window, visibleItem(content, "topic-" + topicId));
        QTRY_COMPARE(controller.selectedTopic(), topicId);
        QTRY_COMPARE(controller.messages().size(), 1);
        auto *bubble = visibleItem(content, "inline-image-" + first); QVERIFY(bubble);
        // The held metadata keeps the reservation expanded (no decoded size).
        QTRY_VERIFY_WITH_TIMEOUT(bubble->width() >= 120
            && bubble->property("imageUrl").toString().isEmpty(), 4000);
        QTRY_VERIFY_WITH_TIMEOUT(*metaArrived, 4000);
        // Late delivery, like a decode lane starved under CI parallel load.
        QTimer::singleShot(600, qApp, [releaseMeta] { if (*releaseMeta) (*releaseMeta)(); });
        // The preview lands within the production contract...
        QTRY_VERIFY_WITH_TIMEOUT(([&] {
            return !bubble->property("imageUrl").toString().isEmpty()
                || bubble->property("failed").toBool();
        })(), 17000);
        QVERIFY2(!bubble->property("failed").toBool(), "late HEIC decode failed");
        // ...and the row collapses to the decoded frame while doing so.
        QTRY_VERIFY_WITH_TIMEOUT(bubble->width() < 120, 8000);
        // The painted pixels follow the collapsed, live geometry.
        QTRY_VERIFY_WITH_TIMEOUT(heicBubbleShowsSolidFill(window, bubble, heicColor), 8000);
    }

    // Issue #638 sec 4/5: a corrupt HEIC (sniffs as HEIC, fails to decode)
    // falls back to the file-card surface in the bubble (failed preview with
    // its save action) and to the viewer display-error slot, where download
    // stays enabled and still saves the original bytes verbatim.
    void corruptHeicFallsBackToFileCardAndDisplayErrorSlotWithDownload()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const QString fileA = QStringLiteral("9f000000-0000-4000-8000-00000000000a");
        const QString fileB = QStringLiteral("9f000000-0000-4000-8000-00000000000b");
        const QString first = QStringLiteral("9e000000-0000-4000-8000-000000000001");
        const QString second = QStringLiteral("9e000000-0000-4000-8000-000000000002");
        const QByteArray png = avatarProbePng(false);
        const QByteArray broken = heicTruncatedFixture(); // sniffs HEIC, fails the decode
        WindowChannelFixture fixture;
        const auto fallback = fixture.server.handler;
        fixture.server.handler = [&](const Request &request) -> Response {
            const auto path = request.target.path();
            if (path.startsWith("/api/workspace/v1/messenger/files/" + fileA)) {
                if (path.endsWith("/actions/download")) {
                    Response result; result.rawBody = png; result.rawContentType = "image/png";
                    return result;
                }
                auto metadata = avatarProbeMetadata(fileA, png);
                metadata["stream_uuid"] = streamId; metadata["name"] = "shot.png";
                return Response{metadata};
            }
            if (path.startsWith("/api/workspace/v1/messenger/files/" + fileB)) {
                if (path.endsWith("/actions/download")) {
                    Response result; result.rawBody = broken; result.rawContentType = "image/heic";
                    return result;
                }
                auto metadata = avatarProbeMetadata(fileB, broken);
                metadata["stream_uuid"] = streamId; metadata["name"] = "trip.heic";
                metadata["content_type"] = "image/heic";
                return Response{metadata};
            }
            if (path.endsWith("/messages/") && request.method == "GET") {
                ++fixture.historyGets;
                return Response{QJsonArray{mediaViewerRow(first, fileA, png.size()),
                                           mediaViewerHeicRow(second, fileB, broken.size())}};
            }
            return fallback(request);
        };
        ApiClient api(nullptr, true); Session session(&api); FileClient files(&api);
        MessageImages images(&api, &session, &files);
        NativeController controller(&api, &session); controller.useFiles(&files);
        NativePreferences preferences(directory.filePath("heic-broken.ini"));
        preferences.setLocale("en"); preferences.setMode("light");
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences, nullptr, nullptr, &images);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto closeBeforeEngine = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard && !closeIncubatedTestWindow(engine, guard.data()))
                QTest::qFail("Corrupt HEIC window did not settle before engine teardown", __FILE__, __LINE__);
        });
        window->resize(1440, 900); QVERIFY(QTest::qWaitForWindowExposed(window));
        window->requestActivate(); QVERIFY(QTest::qWaitForWindowActive(window));
        session.login(fixture.server.origin(), "synthetic", "synthetic");
        QTRY_COMPARE(session.projects().size(), 1); session.selectProject(projectId);
        QTRY_COMPARE(controller.streams().size(), 1); QTRY_VERIFY(controller.channelMembersVerified());
        auto *content = window->contentItem();
        click(window, visibleItem(content, "stream-" + streamId));
        QTRY_COMPARE(controller.topics().size(), 1);
        click(window, visibleItem(content, "topic-" + topicId));
        QTRY_COMPARE(controller.selectedTopic(), topicId);
        QTRY_COMPARE(controller.messages().size(), 2);
        QTRY_VERIFY(visibleItem(content, "inline-image-" + first));
        // The bubble settles the HEIC entry Failed: the file-card surface with
        // its save/retry action replaces the preview (reference display-error
        // fallback; the save-action contract is pinned by
        // receivedBrokenImageKeepsItsAttachmentSaveAction).
        auto *brokenBubble = visibleItem(content, "inline-image-" + second); QVERIFY(brokenBubble);
        QTRY_VERIFY_WITH_TIMEOUT(brokenBubble->property("failed").toBool(), 10000);
        QVERIFY(images.failed(QStringLiteral("urn:image:%1?name=trip.heic&content_type=image%2Fheic&size=%2")
            .arg(fileB, QString::number(broken.size()))));
        // The viewer gallery keeps the broken attachment and marks the slot
        // display-error (reference replaceItem), never dropping it from the strip.
        auto *viewer = controller.mediaViewer();
        clickActiveInlineImage(window, first);
        QTRY_VERIFY(viewer->open());
        QCOMPARE(int(viewer->items().size()), 2);
        click(window, visibleItem(content, "mediaViewer-next"));
        QTRY_VERIFY_WITH_TIMEOUT(([&]{ return viewer->items().at(1).toMap().value("state").toString()
            == QStringLiteral("display-error"); })(), 10000);
        QCOMPARE(viewer->items().at(1).toMap().value("kind").toString(), QString("image"));
        QTRY_VERIFY_WITH_TIMEOUT(([&]{ auto *t = visibleItem(content, "mediaViewer-status");
            return t && t->property("text").toString()
                == QString("This media cannot be displayed. You can download the file instead."); })(), 6000);
        // Unlike a video display-error, an image slot stays downloadable
        // (media-viewer-overlay.ui.tsx:64-68 downloadEnabled).
        QVERIFY(visibleItem(content, "mediaViewer-download")->property("enabled").toBool());
        auto *saveDialog = window->findChild<QObject *>("attachmentSaveDialog"); QVERIFY(saveDialog);
        click(window, visibleItem(content, "mediaViewer-download"));
        QTRY_VERIFY_WITH_TIMEOUT(saveDialog->property("visible").toBool(), 4000);
        QVERIFY(saveDialog->setProperty("currentFolder", QUrl::fromLocalFile(directory.path())));
        QTRY_VERIFY_WITH_TIMEOUT(visibleItem("fileNameTextField"), 4000);
        auto *filename = visibleItem("fileNameTextField");
        click(filename->window(), filename);
        QTest::keySequence(filename->window(), QKeySequence::SelectAll);
        for (const auto character : QByteArray("broken.heic"))
            QTest::keyClick(filename->window(), character);
        QCOMPARE(filename->property("text").toString(), QString("broken.heic"));
        QTRY_VERIFY_WITH_TIMEOUT(dialogButton("Save"), 4000);
        auto *saveButton = dialogButton("Save");
        QSignalSpy saveAccepted(saveDialog, SIGNAL(accepted())); QVERIFY(saveAccepted.isValid());
        click(saveButton->window(), saveButton);
        QTRY_COMPARE_WITH_TIMEOUT(saveAccepted.size(), 1, 4000);
        const auto saved = QDir(directory.path()).filePath("broken.heic");
        QTRY_VERIFY_WITH_TIMEOUT(QFile::exists(saved), 4000);
        QFile savedFile(saved); QVERIFY(savedFile.open(QIODevice::ReadOnly));
        QCOMPARE(savedFile.readAll(), broken); // the original bytes, corrupt or not
        QTest::keyClick(window, Qt::Key_Escape);
        QTRY_VERIFY(!viewer->open());
    }

    void topOverlayBannerRendersAboveSplitWithoutBlockingHeaderClicks()
    {
        WindowBannerFixture fixture;
        QTemporaryDir directory; QVERIFY(directory.isValid());
        NativePreferences preferences(directory.filePath("overlay-banners.ini"));
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard && !closeIncubatedTestWindow(engine, guard.data()))
                QTest::qFail("Overlay banner teardown", __FILE__, __LINE__);
        });
        QVERIFY(QTest::qWaitForWindowExposed(window)); window->requestActivate();
        QVERIFY(QTest::qWaitForWindowActive(window));
        QVERIFY(fixture.start(controller));
        QTRY_VERIFY(api.findChildren<QNetworkReply *>().isEmpty());
        QVERIFY(!visibleItem("connectionBanner"));
        QVERIFY(!visibleItem("bootstrapErrorBanner"));
        // A transport drop raises the critical connection banner over the split.
        fixture.dropRound = true;
        controller.refresh();
        QTRY_VERIFY(visibleItem("connectionBanner"));
        auto *banner = visibleItem("connectionBanner");
        QCOMPARE(banner->property("bannerText").toString(), QString("You are offline."));
        QCOMPARE(banner->property("accent").value<QColor>(), QColor("#d92d20"));
        auto *topBar = visibleItem("topBar"); auto *sidebar = visibleItem("sidebar");
        QVERIFY(topBar && sidebar);
        // The outage also fails the in-flight snapshot, so the bootstrap strip
        // may stack under the connection strip; measure the overlay layer.
        auto *overlay = visibleItem("topBannerOverlay"); QVERIFY(overlay);
        const auto overlayTop = overlay->mapToScene(QPointF(0, 0)).y();
        const auto headerBottom = topBar->mapToScene(QPointF(0, topBar->height())).y();
        const auto splitTop = sidebar->mapToScene(QPointF(0, 0)).y();
        QVERIFY2(overlayTop >= headerBottom - 1, "the overlay starts below the header");
        QVERIFY2(overlayTop <= splitTop + 1, "the overlay sits over the top of the split view");
        QVERIFY(banner->height() > 0);
        // Header clicks keep reaching the top bar while the banner is up.
        click(window, visibleItem("accountMenuButton"));
        QTRY_VERIFY(visibleItem("ownStatusAction"));
        click(window, visibleItem("accountMenuButton")); // second click toggles the account layer closed (#724)
        QTRY_VERIFY(!visibleItem("ownStatusAction"));
        // The next successful response clears the banner again.
        fixture.dropRound = false;
        controller.refresh();
        QTRY_VERIFY(!visibleItem("connectionBanner"));
        // HTTP 429 renders the warning countdown and expires on its own.
        fixture.rateLimitAfterSeconds = 1;
        controller.refresh();
        QTRY_VERIFY(visibleItem("connectionBanner"));
        banner = visibleItem("connectionBanner");
        QVERIFY(banner->property("bannerText").toString().contains("Retrying in"));
        QVERIFY(banner->property("accent").value<QColor>() != QColor("#d92d20"));
        fixture.rateLimitAfterSeconds = 0;
        QTRY_VERIFY(!visibleItem("connectionBanner"));
        // A bootstrap failure shows the Retry banner; the header stays usable
        // and clicking Retry against the healthy server recovers the shell.
        fixture.breakStreams = true;
        controller.refresh();
        QTRY_VERIFY(visibleItem("bootstrapErrorBanner"));
        QVERIFY(visibleItem("bootstrapRetryButton"));
        QVERIFY(!visibleItem("bootstrapErrorText")->property("text").toString().isEmpty());
        click(window, visibleItem("accountMenuButton"));
        QTRY_VERIFY(visibleItem("ownStatusAction"));
        click(window, visibleItem("accountMenuButton")); // second click toggles the account layer closed (#724)
        QTRY_VERIFY(!visibleItem("ownStatusAction"));
        fixture.breakStreams = false;
        click(window, visibleItem("bootstrapRetryButton"));
        QTRY_VERIFY(!visibleItem("bootstrapErrorBanner"));
        QTRY_COMPARE(controller.streams().size(), 1);
        QVERIFY(fixture.streamsGets >= 4);
    }

    // Issue #122: the reference expandable bottom toolbar persists its
    // expansion (settings.model.ts composerToolbarExpanded, default false)
    // and keeps 32px hit areas, h-7 w-px bg-border-subtle separators,
    // mr-[52px] send clearance and the pl-2 leading inset
    // (message-composer-toolbar.ui.tsx, message-composer-styles.lib.ts).
    void expandedComposerToolbarStaysInsideTheWindow_data()
    {
        QTest::addColumn<QString>("locale");
        QTest::addColumn<QString>("mode");
        QTest::addColumn<QString>("initialDraft");
        for (const auto &locale : {QString("en"), QString("ru")})
            for (const auto &mode : {QString("light"), QString("dark")})
                for (const auto &draft : {QString(), QString("word")})
                    QTest::newRow(qPrintable(locale + '-' + mode + (draft.isEmpty() ? "-empty" : "-short")))
                        << locale << mode << draft;
    }

    void expandedComposerToolbarStaysInsideTheWindow()
    {
        QFETCH(QString, locale); QFETCH(QString, mode); QFETCH(QString, initialDraft);
        QTest::failOnWarning();
        WindowChannelFixture fixture; fixture.sourceScene = true;
        const auto fallback = fixture.server.handler;
        int sends = 0;
        fixture.server.handler = [&, fallback](const Request &request) -> Response {
            if (request.method == "POST" && request.target.path().endsWith("/messages/")) ++sends;
            return fallback(request);
        };
        QTemporaryDir directory; QVERIFY(directory.isValid());
        NativePreferences preferences(directory.filePath("toolbar-visibility.ini"));
        preferences.setLocale(locale); preferences.setMode(mode);
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        const auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard && !closeIncubatedTestWindow(engine, guard.data()))
                QTest::qFail("Toolbar visibility teardown", __FILE__, __LINE__);
        });
        QVERIFY(QTest::qWaitForWindowExposed(window)); window->requestActivate();
        QVERIFY(QTest::qWaitForWindowActive(window));
        QVERIFY(startComposerEmojiFixture(fixture, controller, session));
        QTRY_COMPARE(controller.selectedTopic(), topicId);
        auto *content = window->contentItem();
        auto *composer = item(content, "messageComposer"); QVERIFY(composer);
        auto *shell = item(content, "messageComposerShell"); QVERIFY(shell);
        auto *toolbar = item(content, "composerToolbarRow"); QVERIFY(toolbar);
        auto *editorViewport = composer->parentItem();
        while (editorViewport && editorViewport->metaObject()->indexOfProperty("contentY") < 0)
            editorViewport = editorViewport->parentItem();
        QVERIFY(editorViewport);
        const auto sceneRect = [](QQuickItem *target) {
            return target->mapRectToScene(QRectF(QPointF{}, target->size()));
        };
        const auto insideWindow = [&](QQuickItem *target) {
            return target && target->isVisible() && target->width() > 0 && target->height() > 0
                && QRectF(0, 0, window->width(), window->height()).contains(sceneRect(target));
        };
        const auto replaceDraft = [&](const QString &text) {
            QVERIFY(insideWindow(editorViewport));
            click(window, editorViewport);
            QTRY_VERIFY(composer->hasActiveFocus());
            QTest::keyClick(window, Qt::Key_A, Qt::ControlModifier);
            if (text.isEmpty()) QTest::keyClick(window, Qt::Key_Backspace);
            else {
                QInputMethodEvent input; input.setCommitString(text);
                QCoreApplication::sendEvent(composer, &input);
            }
            QTRY_COMPARE(controller.draft(), text);
        };
        const QStringList actions{"composerToolbarCollapse", "composerFormatLink", "composerFormatBold",
            "composerFormatItalic", "composerFormatStrikethrough", "composerFormatNumbered",
            "composerFormatBulleted", "composerFormatQuote", "composerFormatCodeBlock",
            "composerFormatCode", "composerFormatSpoiler"};
        const auto verifyToolbar = [&] {
            QTRY_VERIFY(toolbar->isVisible());
            // Wait for the rendered scene, not just the visibility notification.
            QTest::qWait(50);
            const auto frame = window->grabWindow(); QVERIFY(!frame.isNull());
            QVERIFY(insideWindow(shell));
            // #661: the toolbar row now carries the attach/emoji/poll triggers
            // too; past the viewport the reference ScrollArea scrolls instead
            // of shrinking, so an action is legal either inside the shell or
            // inside the row's scrollable extent (clip:true hides the tail).
            const auto shellRect = sceneRect(shell);
            const auto rowRect = sceneRect(toolbar);
            const auto scrollRight = rowRect.left()
                + toolbar->property("contentWidth").toReal();
            for (const auto &name : actions) {
                auto *action = visibleItem(content, name); QVERIFY2(action, qPrintable(name));
                const auto rect = sceneRect(action);
                const auto details = QString("%1: action (%2,%3 %4x%5), shell (%6,%7 %8x%9), window %10x%11")
                    .arg(name).arg(rect.x()).arg(rect.y()).arg(rect.width()).arg(rect.height())
                    .arg(shellRect.x()).arg(shellRect.y())
                    .arg(shellRect.width()).arg(shellRect.height()).arg(window->width()).arg(window->height());
                const bool fits = shellRect.contains(rect);
                const bool scrolls = rect.left() >= rowRect.left() - 0.5
                    && rect.right() <= scrollRight + 1.0
                    && rect.top() >= shellRect.top() && rect.bottom() <= shellRect.bottom();
                QVERIFY2((fits && insideWindow(action)) || scrolls, qPrintable(details));
                QCOMPARE(action->size(), QSizeF(32, 32));
            }
            QVERIFY(sceneRect(editorViewport).bottom() <= sceneRect(toolbar).top());
        };
        QVERIFY(!toolbar->isVisible());
        QTRY_COMPARE(shell->height(), 57.0); // Keep the existing compact input geometry.
        replaceDraft(initialDraft);
        auto *expand = visibleItem(content, "composerToolbarExpand"); QVERIFY(insideWindow(expand));
        click(window, expand);
        verifyToolbar(); if (QTest::currentTestFailed()) return;
        const auto captures = qEnvironmentVariable("CASSI_NATIVE_TOOLBAR_VISIBILITY_CAPTURE_DIR");
        if (!captures.isEmpty())
            QVERIFY(window->grabWindow().save(QDir(captures).filePath(
                locale + '-' + mode + (initialDraft.isEmpty() ? "-empty.png" : "-short.png"))));

        // An actual in-window pointer click formats the draft and restores its caret.
        replaceDraft("word");
        QTest::keyClick(window, Qt::Key_A, Qt::ControlModifier);
        auto *bold = visibleItem(content, "composerFormatBold"); QVERIFY(insideWindow(bold));
        click(window, bold);
        QTRY_COMPARE(controller.draft(), QString("**word**"));
        QTRY_VERIFY(composer->hasActiveFocus());
        QCOMPARE(composer->property("cursorPosition").toInt(), 8);
        verifyToolbar(); if (QTest::currentTestFailed()) return;

        // Growing and shrinking the input cannot push the toolbar out of its shell.
        replaceDraft(QString("line\n").repeated(12) + "last");
        verifyToolbar(); if (QTest::currentTestFailed()) return;
        replaceDraft("word");
        verifyToolbar(); if (QTest::currentTestFailed()) return;
        window->resize(1100, 680);
        QTRY_COMPARE(window->size(), QSize(1100, 680));
        verifyToolbar(); if (QTest::currentTestFailed()) return;
        replaceDraft("");
        verifyToolbar(); if (QTest::currentTestFailed()) return;
        auto *collapse = visibleItem(content, "composerToolbarCollapse"); QVERIFY(insideWindow(collapse));
        click(window, collapse);
        QTRY_VERIFY(!toolbar->isVisible());
        QTRY_COMPARE(shell->height(), 57.0);
        expand = visibleItem(content, "composerToolbarExpand"); QVERIFY(insideWindow(expand));
        click(window, expand);
        verifyToolbar(); if (QTest::currentTestFailed()) return;
        window->resize(1440, 900);
        QTRY_COMPARE(window->size(), QSize(1440, 900));
        verifyToolbar();
        QCOMPARE(controller.draft(), QString());
        QCOMPARE(sends, 0);
    }

    // #722: the one-line compact composer must keep the formatting toggle
    // vertically centered with its neighbours. The toggle grid
    // (composerLeadingControls) and the attach/emoji grid (composerCompactActions)
    // sit inside the field viewport (composerFieldViewport); bottom-pinning them
    // drops the toggle below the placeholder line. The reference centers the
    // compact row controls (message-composer.ui.tsx compactInline).
    void compactComposerToggleCentersWithInputRow()
    {
        QTest::failOnWarning();
        WindowChannelFixture fixture; fixture.sourceScene = true;
        QTemporaryDir directory; QVERIFY(directory.isValid());
        NativePreferences preferences(directory.filePath("toggle-align.ini"));
        preferences.setLocale(QStringLiteral("en")); preferences.setMode(QStringLiteral("light"));
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        const auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard && !closeIncubatedTestWindow(engine, guard.data()))
                QTest::qFail("Toggle alignment teardown", __FILE__, __LINE__);
        });
        QVERIFY(QTest::qWaitForWindowExposed(window)); window->requestActivate();
        QVERIFY(QTest::qWaitForWindowActive(window));
        QVERIFY(startComposerEmojiFixture(fixture, controller, session));
        QTRY_COMPARE(controller.selectedTopic(), topicId);
        auto *content = window->contentItem();
        auto *toggle = visibleItem(content, "composerToolbarExpand"); QVERIFY(toggle);
        auto *attach = visibleItem(content, "attachButton"); QVERIFY(attach);
        auto *emoji = visibleItem(content, "composerEmojiButton"); QVERIFY(emoji);
        auto *viewport = visibleItem(content, "composerFieldViewport"); QVERIFY(viewport);
        const auto centerY = [](QQuickItem *target) {
            return target->mapRectToScene(QRectF(QPointF{}, target->size())).center().y();
        };
        // Empty and short drafts must keep the one-line geometry (shell 57 px).
        auto *shell = item(content, "messageComposerShell"); QVERIFY(shell);
        QTRY_COMPARE(shell->height(), 57.0);
        controller.setDraft(QStringLiteral("word"));
        QTRY_COMPARE(shell->height(), 57.0);
        const double viewCenter = centerY(viewport);
        const double toggleCenter = centerY(toggle);
        const double attachCenter = centerY(attach);
        const double emojiCenter = centerY(emoji);
        qInfo() << "cassi-722 centers" << "viewport" << viewCenter
                << "toggle" << toggleCenter << "attach" << attachCenter << "emoji" << emojiCenter;
        QStringList deviations;
        const auto check = [&deviations](const char *name, double delta, double limit) {
            if (!(qAbs(delta) <= limit))
                deviations << QStringLiteral("%1 delta %2 > %3")
                    .arg(QLatin1String(name)).arg(delta, 0, 'f', 2).arg(limit);
        };
        check("toggle-attach", toggleCenter - attachCenter, 2.0);
        check("toggle-emoji", toggleCenter - emojiCenter, 2.0);
        check("toggle-viewport", toggleCenter - viewCenter, 3.0);
        check("attach-viewport", attachCenter - viewCenter, 3.0);
        QCOMPARE(deviations, QStringList());
    }

    void composerFormattingToolbarExpansionPersistsAcrossRecreation()
    {
        WindowChannelFixture fixture; fixture.sourceScene = true;
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const auto settingsPath = directory.filePath("toolbar-expansion.ini");
        for (int lifetime = 0; lifetime < 3; ++lifetime) {
            NativePreferences preferences(settingsPath);
            preferences.setLocale("en"); preferences.setMode("light");
            ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
            QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences);
            auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
            auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
                if (guard) closeIncubatedTestWindow(engine, guard.data());
            });
            QVERIFY(QTest::qWaitForWindowExposed(window)); window->requestActivate();
            QVERIFY(QTest::qWaitForWindowActive(window));
            QVERIFY(startComposerEmojiFixture(fixture, controller, session));
            QTRY_VERIFY(controller.selectedTopic() == topicId);
            const auto view = [&](const QString &name) { return visibleItem(window->contentItem(), name); };
            auto *composer = view("messageComposer"); QVERIFY(composer && composer->isEnabled());
            auto *toolbar = item(window->contentItem(), "composerToolbarRow"); QVERIFY(toolbar);
            if (lifetime == 0) {
                // settings.model.ts:74: the default composer starts collapsed
                // with only the single expand toggle in the input row.
                QVERIFY(!toolbar->isVisible());
                auto *expandToggle = view("composerToolbarExpand"); QVERIFY(expandToggle);
                QVERIFY(!view("composerToolbarCollapse"));
                // message-composer-styles.lib.ts TOOLBAR_BTN h-8 w-8.
                QCOMPARE(expandToggle->width(), 32.0);
                QCOMPARE(expandToggle->height(), 32.0);
                const auto compactAxis = expandToggle->mapToItem(window->contentItem(), QPointF{}).x();
                click(window, expandToggle);
                QTRY_VERIFY(toolbar->isVisible());
                QSignalSpy painted(window, &QQuickWindow::frameSwapped);
                window->update();
                QTRY_VERIFY(!painted.isEmpty());
                auto *collapseToggle = view("composerToolbarCollapse"); QVERIFY(collapseToggle);
                // COMPOSER_LEADING_CONTROLS_INSET pl-2: the collapse toggle
                // sits 8px from the toolbar row's left edge.
                QCOMPARE(qRound(collapseToggle->mapToItem(window->contentItem(), QPointF{}).x()
                    - toolbar->mapToItem(window->contentItem(), QPointF{}).x()), 8);
                // Reference comment: both 32px toggles stay on one vertical axis.
                QCOMPARE(qRound(collapseToggle->mapToItem(window->contentItem(), QPointF{}).x()),
                    qRound(compactAxis));
                // message-composer-styles.lib.ts TOOLBAR_BTN: every action
                // keeps the 32x32 hit area.
                const QStringList actions{"composerFormatLink", "composerFormatBold",
                    "composerFormatItalic", "composerFormatStrikethrough",
                    "composerFormatNumbered", "composerFormatBulleted",
                    "composerFormatQuote", "composerFormatCodeBlock",
                    "composerFormatCode", "composerFormatSpoiler"};
                for (const auto &name : actions) {
                    auto *action = view(name); QVERIFY2(action, qPrintable(name));
                    QVERIFY2(action->isEnabled(), qPrintable(name));
                    QCOMPARE(action->width(), 32.0);
                    QCOMPARE(action->height(), 32.0);
                }
                // message-composer-toolbar.ui.tsx separators: h-7 w-px bg-border-subtle.
                // The reference renders FOUR spans (ui.tsx:148/160/210/240) and its own
                // test pins four (ui.test.tsx:31 at e0194ff); the expanded toolbar gains
                // the attach/emoji separator the poll-trigger placement (#661) requires.
                const auto separators = toolbar->findChildren<QQuickItem *>("composerToolbarSeparator");
                QCOMPARE(separators.size(), 4);
                for (auto *separator : separators) {
                    QCOMPARE(separator->width(), 1.0);
                    QCOMPARE(separator->height(), 28.0);
                    QCOMPARE(QQmlProperty::read(separator, "color").value<QColor>(),
                        QColor(window->property("colors").toMap().value("border-subtle").toString()));
                }
                // COMPOSER_TOOLBAR_SEND_CLEARANCE mr-[52px]: 40px send + 12px row gap.
                auto *send = view("sendButton"); QVERIFY(send);
                const auto sendRight = send->mapToItem(window->contentItem(), QPointF(send->width(), 0)).x();
                const auto toolbarRight
                    = toolbar->mapToItem(window->contentItem(), QPointF(toolbar->width(), 0)).x();
                QCOMPARE(qRound(sendRight - toolbarRight), 52);
                // The expansion now persists as true for the next lifetime.
            } else if (lifetime == 1) {
                QTRY_VERIFY_WITH_TIMEOUT(toolbar->isVisible(), 2000); // persisted expansion
                click(window, view("composerToolbarCollapse"));
                QTRY_VERIFY(!toolbar->isVisible()); // persisted collapse
            } else {
                QVERIFY(!toolbar->isVisible()); // collapsed choice survived recreation
                QVERIFY(view("composerToolbarExpand"));
            }
            QVERIFY(closeIncubatedTestWindow(engine, window)); close.dismiss();
        }
    }

    void composerTimePickerPreservesBothFallBackInstants()
    {
        if (!qEnvironmentVariableIsSet("WORKSPACE_COMPOSER_TIME_FOLD")) {
            QProcess child;
            auto environment = QProcessEnvironment::systemEnvironment();
            environment.insert("TZ", "America/New_York");
            environment.insert("WORKSPACE_COMPOSER_TIME_FOLD", "1");
            child.setProcessEnvironment(environment);
            child.setProcessChannelMode(QProcess::MergedChannels);
            child.start(QCoreApplication::applicationFilePath(),
                        {"composerTimePickerPreservesBothFallBackInstants", "-o", "-,txt"});
            QVERIFY(child.waitForFinished(30000));
            const QByteArray output = child.readAll();
            QVERIFY2(child.exitStatus() == QProcess::NormalExit && child.exitCode() == 0, output.constData());
            return;
        }
        // The second 01:30 on the November transition is 06:30 UTC.
        // Both UTC instants have the same local hour, minute and second.
        const auto second = QDateTime::fromString("2026-11-01T06:30:00Z", Qt::ISODate);
        QCOMPARE(second.toLocalTime().time(), QTime(1, 30));
        QQmlEngine engine;
        QQmlComponent component(&engine, QUrl("qrc:/workspace/qml/NativeComposerTimePicker.qml"));
        QVERIFY2(component.isReady(), qPrintable(component.errorString()));
        QQuickWindow window;
        window.resize(640, 480);
        const QVariantMap colors{{"bg-elevated", "white"}, {"border-subtle", "gray"},
            {"text-primary", "black"}, {"text-muted", "gray"}};
        std::unique_ptr<QObject> picker(component.createWithInitialProperties({
            {"parent", QVariant::fromValue(window.contentItem())}, {"colors", colors}, {"localeName", "en"}}));
        QVERIFY2(picker, qPrintable(component.errorString()));
        window.show(); QVERIFY(QTest::qWaitForWindowExposed(&window));
        QVERIFY(QMetaObject::invokeMethod(picker.get(), "open"));
        auto *hours = picker->findChild<QObject *>("composerTimeHours");
        auto *minutes = picker->findChild<QObject *>("composerTimeMinutes");
        auto *seconds = picker->findChild<QObject *>("composerTimeSeconds");
        auto *insert = picker->findChild<QObject *>("composerTimeInsert");
        QVERIFY(hours && minutes && seconds && insert);
        for (const auto &expected : {second.addSecs(-3600), second}) {
            picker->setProperty("openedAt", expected.addSecs(-60));
            picker->setProperty("selectedDay", expected);
            hours->setProperty("value", 1); minutes->setProperty("value", 30); seconds->setProperty("value", 0);
            QCOMPARE(picker->property("instant").toDateTime().toUTC(), expected);
            QVERIFY(insert->property("enabled").toBool());
            picker->setProperty("month", expected);
            QQuickItem *day = nullptr;
            QTRY_VERIFY((day = visibleItem(window.contentItem(), "composerCalendarDay-1")));
            click(&window, day);
            QCOMPARE(picker->property("instant").toDateTime().toUTC(), expected);
        }
    }

