        QCOMPARE(qRound(backButton->width()), 32); QCOMPARE(qRound(backButton->height()), 32);
        QCOMPARE(QQmlProperty(backButton, "icon.width").read().toInt(), 16);
        // aria labels via common.close / common.back.
