    void pollCreateDialogOpensCenteredInWindow()
    {
        // Bug #667: the create-poll dialog opened at the top edge. It must use
        // the same positioning as the other dialogs (anchors.centerIn: parent,
        // cf. NativePollManagementDialog) in both normal and resized windows.
        QTemporaryDir directory; QVERIFY(directory.isValid());
        WindowChannelFixture fixture;
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
        NativePreferences preferences(directory.filePath("poll-center.ini"));
        preferences.setLocale("en"); preferences.setMode("light");
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences, nullptr, nullptr);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard && !closeIncubatedTestWindow(engine, guard.data()))
                QTest::qFail("Poll create centering window did not settle before engine teardown", __FILE__, __LINE__);
        });
        window->resize(1440, 900); QVERIFY(QTest::qWaitForWindowExposed(window));
        window->requestActivate(); QVERIFY(QTest::qWaitForWindowActive(window));
        session.login(fixture.server.origin(), "synthetic", "synthetic");
        QTRY_COMPARE(session.projects().size(), 1); session.selectProject(projectId);
        QTRY_COMPARE(controller.streams().size(), 1);
        QTRY_VERIFY(controller.channelMembersVerified());
        preferences.setOwner(controller.ownerKey());
        click(window, visibleItem(window->contentItem(), "stream-" + streamId));
        QTRY_COMPARE(controller.topics().size(), 1);
        click(window, visibleItem(window->contentItem(), "topic-" + topicId));
        QTRY_VERIFY(controller.selectedStream() == streamId && controller.selectedTopic() == topicId);
        QTRY_VERIFY(!controller.busy());
        click(window, expandedComposerPollTrigger(window));
        auto *dialog = window->findChild<QObject *>("pollCreateDialog"); QVERIFY(dialog);
        QTRY_VERIFY(dialog->property("visible").toBool());
        // QQuickPopup is a QObject, not a QQuickItem: read geometry through the
        // Popup's own x/y/width/height properties and its parent item.
        auto *par = qobject_cast<QQuickItem *>(dialog->property("parent").value<QObject *>());
        QVERIFY(par);
        const auto centered = [&]{
            const qreal px = dialog->property("x").toReal(), py = dialog->property("y").toReal();
            const qreal pw = dialog->property("width").toReal(), ph = dialog->property("height").toReal();
            return pw > 0 && ph > 0
                && qAbs(px + pw / 2.0 - par->width() / 2.0) <= 2.0
                && qAbs(py + ph / 2.0 - par->height() / 2.0) <= 2.0;
        };
        // Centered within a 2 px band after the geometry pass settles.
        QTRY_VERIFY_WITH_TIMEOUT(centered(), 5000);
        // A window resize keeps the dialog centered (maximize analogue: the
        // popup re-centers against the overlay, which tracks the window).
        // First require the overlay to reach the requested size: resize delivery
        // is asynchronous, and until it lands the popup's OLD geometry against
        // the OLD parent size still satisfies centered() - the assertion would
        // pass vacuously before any re-centering happened.
        window->resize(1024, 700);
        QTRY_VERIFY_WITH_TIMEOUT(
            qAbs(par->width() - 1024.0) <= 2.0 && qAbs(par->height() - 700.0) <= 2.0, 5000);
        QTRY_VERIFY_WITH_TIMEOUT(centered(), 5000);
        click(window, window->findChild<QQuickItem *>("pollCancelButton"));
        QTRY_VERIFY(!dialog->property("visible").toBool());
    }

    void pollCreateDialogDeadlineMustBeFuture()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        WindowChannelFixture fixture;
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
        NativePreferences preferences(directory.filePath("poll-create-deadline.ini"));
        preferences.setLocale("en"); preferences.setMode("light");
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences, nullptr, nullptr);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard && !closeIncubatedTestWindow(engine, guard.data()))
                QTest::qFail("Poll deadline window did not settle before engine teardown", __FILE__, __LINE__);
        });
        window->resize(1440, 900); QVERIFY(QTest::qWaitForWindowExposed(window));
        window->requestActivate(); QVERIFY(QTest::qWaitForWindowActive(window));
        session.login(fixture.server.origin(), "synthetic", "synthetic");
        QTRY_COMPARE(session.projects().size(), 1); session.selectProject(projectId);
        QTRY_COMPARE(controller.streams().size(), 1);
        preferences.setOwner(controller.ownerKey());
        click(window, visibleItem(window->contentItem(), "stream-" + streamId));
        QTRY_COMPARE(controller.topics().size(), 1);
        click(window, visibleItem(window->contentItem(), "topic-" + topicId));
        QTRY_VERIFY(!controller.busy());
        click(window, expandedComposerPollTrigger(window));
        auto *dialog = window->findChild<QObject *>("pollCreateDialog"); QVERIFY(dialog);
        QTRY_VERIFY(dialog->property("visible").toBool());
        dialog->findChildren<QObject *>("pollQuestionField").at(0)->setProperty("text", "When?");
        dialog->findChildren<QObject *>("pollAnswerField").at(0)->setProperty("text", "First");
        QTRY_COMPARE(dialog->findChildren<QObject *>("pollAnswerField").size(), 2);
        dialog->findChildren<QObject *>("pollAnswerField").at(1)->setProperty("text", "Second");
        auto *create = window->findChild<QQuickItem *>("pollCreateButton"); QVERIFY(create);
QTRY_VERIFY(create->property("enabled").toBool());
        click(window, window->findChild<QQuickItem *>("pollSettingsButton"));
        // The settings section flows below the form fold. Two harness traps:
        // mapToScene on items inside a Popup answers in popup-local space
        // (deprecated API), and static contentY writes are not clamped to the
        // Flickable bounds here, so an unclamped write scrolls the action out
        // through the top. Scroll to a computed max offset and dispatch against
        // window-root coordinates only after the layout stops changing.
        auto *flick = window->findChild<QQuickItem *>("pollFormFlickable"); QVERIFY(flick);
        auto *deadlineAction = window->findChild<QQuickItem *>("pollDeadlineAction"); QVERIFY(deadlineAction);
        const auto clickInRoot = [window](QQuickItem *target) {
            const QPointF center = target->mapToItem(window->contentItem(),
                QPointF(target->width() / 2, target->height() / 2));
            QTest::mouseClick(window, Qt::LeftButton, {}, center.toPoint());
        };
        const auto bringIntoView = [flick, deadlineAction, window]() {
            qreal lastHeight = -1.0;
            for (int pass = 0; pass < 60; ++pass) {
                QTest::qWait(50);
                const qreal contentH = flick->property("contentHeight").toReal();
                const qreal maxScroll = qMax(0.0, contentH - flick->height());
                const qreal centerY = deadlineAction->mapToItem(window->contentItem(),
                    QPointF(0, deadlineAction->height() / 2)).y();
                const qreal viewTop = flick->mapToItem(window->contentItem(), QPointF(0, 0)).y();
                const qreal viewBottom = viewTop + flick->height();
                if (contentH == lastHeight && deadlineAction->isVisible()
                    && centerY > viewTop + 4.0 && centerY < viewBottom - 4.0)
                    return;
                lastHeight = contentH;
                flick->setProperty("contentY", maxScroll);
            }
            QFAIL("the deadline action never stayed inside the form viewport");
        };
        bringIntoView();
        clickInRoot(deadlineAction);
        auto *dateField = window->findChild<QObject *>("pollDeadlineDateField"); QVERIFY(dateField);
        QTRY_VERIFY(dateField->property("visible").toBool());
        dateField->setProperty("text", "2020-01-01");
        window->findChild<QObject *>("pollDeadlineTimeField")->setProperty("text", "10:00");
        // A past deadline blocks Create and surfaces the reference hint.
        auto *invalid = window->findChild<QObject *>("pollDeadlineInvalidLabel"); QVERIFY(invalid);
        QTRY_VERIFY(invalid->property("visible").toBool());
        QVERIFY(!create->property("enabled").toBool());
        dateField->setProperty("text", "2099-01-01");
        QTRY_VERIFY(create->property("enabled").toBool());
        QVERIFY(!invalid->property("visible").toBool());
        // Removing the deadline returns to the no-deadline state.
        bringIntoView();
        clickInRoot(deadlineAction);
        QTRY_VERIFY(!dateField->property("visible").toBool());
        QVERIFY(create->property("enabled").toBool());
    }

