    // #141: opening a populated text-only topic must not livelock the Qt Quick
    // layout (GUI thread pinned at ~1 CPU and unbounded RSS growth, reported
    // against 0.10.0; both direct topic selection and a message deep link from
    // a populated channel aggregate reproduced it). A layout livelock hangs
    // the GUI thread inside polish, which would starve an in-process test's
    // own watchdog, so the scene runs in a child process (the cachePhase
    // worker pattern): the parent serves the fixture through MockServer,
    // reads the child's FREEZEPROBE report line, and treats a silent child as
    // the reproduction.
    void openingPopulatedTopicKeepsTheGuiResponsive_data()
    {
        QTest::addColumn<QString>("scenario");
        QTest::newRow("topic-open") << QStringLiteral("topic-open");
        QTest::newRow("aggregate-deeplink") << QStringLiteral("aggregate-deeplink");
        QTest::newRow("repeat-switch") << QStringLiteral("repeat-switch");
        QTest::newRow("cache-restore") << QStringLiteral("cache-restore");
        QTest::newRow("topic-open-wide") << QStringLiteral("topic-open-wide");
        QTest::newRow("topic-open-reported-size") << QStringLiteral("topic-open-reported-size");
    }

    void openingPopulatedTopicKeepsTheGuiResponsive()
    {
        QFETCH(QString, scenario);
        // The fixture mirrors the live report in the issue: the affected topic
        // caches a latest page of 50 markdown messages, longest body 480
        // characters, seven date groups, mixed peer and own author runs,
        // inline references, and reaction footers (five rows, seven reaction
        // entries, total count nine). The reporter follow-up adds the two
        // missing shapes: ten leading reply frames "[Name](urn:quote:uuid)"
        // whose targets all live on the same page (three of them quoting rows
        // that carry an image reference, no quote chains), and five urn:image
        // references - four ordinary Markdown links without dimension
        // parameters plus one standalone Markdown image declaring a 1309x715
        // PNG that the real message-image pipeline decodes during layout.
        const QString otherPeer = QStringLiteral("99999999-9999-4999-8999-999999999999");
        QTemporaryDir cacheDir;
        QVERIFY(cacheDir.isValid());
        int historyDelay = 0;
        int restoreReadPosts = 0;
        const QByteArray standalonePng = freezeProbeStandalonePng();
        QVERIFY(standalonePng.size() > 1000);
        const QImage standaloneDecoded = QImage::fromData(standalonePng, "PNG");
        QCOMPARE(standaloneDecoded.size(), QSize(1309, 715));
        const QStringList imageFiles{
            QStringLiteral("a5140000-0000-4000-8000-000000000001"), // standalone 1309x715
            QStringLiteral("a5140000-0000-4000-8000-000000000002"),
            QStringLiteral("a5140000-0000-4000-8000-000000000003"),
            QStringLiteral("a5140000-0000-4000-8000-000000000004"),
            QStringLiteral("a5140000-0000-4000-8000-000000000005")};
        const QString standaloneUrn = QStringLiteral(
            "urn:image:%1?name=photo.png&content_type=image%2Fpng&w=1309&h=715&size=%2")
            .arg(imageFiles.first(), QString::number(standalonePng.size()));
        const auto bodyFor = [&](int number) {
            switch (number % 6) {
            case 0: return QStringLiteral("Short reply.");
            case 1: return QStringLiteral("Agreed - ship it today. cc [Alice](urn:user:%1) 🚀")
                .arg(channelPeer);
            case 2: return QStringLiteral("Deploy notes [runbook](https://example.invalid/runbook) plus "
                "[status board](https://example.invalid/status) for the release train.");
            case 3: return QStringLiteral("Первая строка\nВторая строка\nТретья строка\nFourth line");
            case 4: {
                const QString filler = QStringLiteral(
                    "wrap pressure across the bubble width while references stay inline and reactions sit in the footer ");
                QString text = filler;
                while (text.size() < 460)
                    text += filler;
                return text.left(480);
            }
            default: return QStringLiteral("Mixed reference [topic](https://example.invalid/t) and a multi\nline tail for wrap variance.");
            }
        };
        const auto rowFor = [&](int number, const QString &topic, const QString &uuidPrefix) {
            QString body = bodyFor(number);
            if (topic == topicId && number == 31)
                body = QStringLiteral("Фото дня\n\n![photo.png](%1)").arg(standaloneUrn);
            else if (topic == topicId && (number == 7 || number == 17 || number == 27 || number == 47))
                body += QStringLiteral(" [вложение](urn:image:%1)")
                    .arg(number == 47 ? imageFiles.at(4) : imageFiles.at(number / 10 + 1));
            auto entry = message(body,
                QString("%1-0000-4000-8000-%2").arg(uuidPrefix)
                    .arg(number + 1, 12, 10, QLatin1Char('0')), topic);
            const bool own = number % 5 >= 2 && number % 5 < 4;
            entry["author_uuid"] = own ? userId : (number % 5 == 0 ? channelPeer : otherPeer);
            entry["is_own"] = own;
            entry["created_at"] = QDateTime(QDate(2026, 1, 1).addDays(number / 8), QTime(10, 0))
                .addSecs(number).toString(Qt::ISODateWithMs);
            if (topic == topicId) {
                // Reactions on five rows: seven reaction entries, total count nine.
                switch (number) {
                case 5:
                    entry["reactions"] = QJsonObject{{"heart", 2}, {"+1", 1}};
                    entry["reaction_users"] = QJsonObject{{"heart", QJsonArray{userId, channelPeer}},
                        {"+1", QJsonArray{userId}}};
                    break;
                case 12:
                    entry["reactions"] = QJsonObject{{"eyes", 1}};
                    entry["reaction_users"] = QJsonObject{{"eyes", QJsonArray{channelPeer}}};
                    break;
                case 23:
                    entry["reactions"] = QJsonObject{{"rocket", 2}, {"tada", 1}};
                    entry["reaction_users"] = QJsonObject{{"rocket", QJsonArray{userId, channelPeer}},
                        {"tada", QJsonArray{userId}}};
                    break;
                case 34:
                    entry["reactions"] = QJsonObject{{"heart", 1}};
                    entry["reaction_users"] = QJsonObject{{"heart", QJsonArray{channelPeer}}};
                    break;
                case 41:
                    entry["reactions"] = QJsonObject{{"+1", 1}};
                    entry["reaction_users"] = QJsonObject{{"+1", QJsonArray{userId}}};
                    break;
                default: break;
                }
            }
            return entry;
        };
        QJsonArray primary, secondary;
        for (int number = 0; number < 50; ++number)
            primary.append(rowFor(number, topicId, QStringLiteral("81000000")));
        for (int number = 0; number < 20; ++number)
            secondary.append(rowFor(number, secondTopicId, QStringLiteral("82000000")));
        {   // Ten leading reply frames (reporter follow-up): the wire format is
            // "[Name](urn:quote:uuid)" + blank line + answer
            // (docs/NATIVE_DESKTOP_REPLIES.md). Every target lives on this same
            // page and three targets carry an urn:image reference; no reply
            // targets another reply, so the page has no quote chains.
            const QList<QPair<int, int>> replies{{2, 7}, {6, 17}, {12, 27}, {19, 0}, {24, 4},
                {29, 9}, {34, 13}, {39, 21}, {44, 30}, {48, 36}};
            for (const auto &reply : replies) {
                auto row = primary.at(reply.first).toObject();
                const auto target = primary.at(reply.second).toObject().value("uuid").toString();
                row["content"] = QStringLiteral("[Alice](urn:quote:%1)\n\nТак, принял — разбираюсь по этому треду.").arg(target);
                primary.replace(reply.first, row);
            }
        }
        const QString anchor = primary.at(24).toObject().value("uuid").toString();
        QJsonArray combined;
        {   // The aggregate view shows the newest 50 rows across both topics.
            QList<QJsonObject> merged;
            for (const auto &value : primary)
                merged.append(value.toObject());
            for (const auto &value : secondary)
                merged.append(value.toObject());
            std::stable_sort(merged.begin(), merged.end(), [](const QJsonObject &left, const QJsonObject &right) {
                return left.value("created_at").toString() < right.value("created_at").toString(); });
            for (auto it = merged.cend() - std::min<qsizetype>(50, merged.size()); it != merged.cend(); ++it)
                combined.append(*it);
        }
        const auto streamDto = [&] {
            return QJsonObject{{"uuid", streamId}, {"project_id", projectId}, {"name", "Freeze probe"},
                {"encryption", false}, {"unread_count", primary.size() + secondary.size()},
                {"active_unread_count", primary.size() + secondary.size()}, {"passive_unread_count", 0},
                {"last_message_uuid", primary.last().toObject().value("uuid")}};
        };
        const auto topicDto = [&](const QString &id) {
            const auto &rows = id == topicId ? primary : secondary;
            return QJsonObject{{"uuid", id}, {"project_id", projectId}, {"stream_uuid", streamId},
                {"name", id == topicId ? "Freeze probe topic" : "Probe companion"},
                {"unread_count", rows.size()}, {"active_unread_count", rows.size()}, {"passive_unread_count", 0},
                {"last_message_uuid", rows.last().toObject().value("uuid")}};
        };
        MockServer server;
        static const QLatin1String filesPrefix("/api/workspace/v1/messenger/files/");
        server.handler = [&](const Request &request) -> Response {
            const auto path = request.target.path();
            if (path.endsWith("/streams/")) return Response{QJsonArray{streamDto()}};
            if (path.endsWith("/streams/" + streamId)) return Response{streamDto()};
            if (path.endsWith("/users/")) return Response{QJsonArray{
                QJsonObject{{"uuid", userId}, {"username", "cassi"}},
                QJsonObject{{"uuid", channelPeer}, {"username", "alice"}, {"first_name", "Alice"}},
                QJsonObject{{"uuid", otherPeer}, {"username", "bob"}, {"first_name", "Bob"}}}};
            if (path.endsWith("/stream_topics/"))
                return Response{QJsonArray{topicDto(topicId), topicDto(secondTopicId)}};
            if (path.endsWith("/stream_topics/" + topicId)) return Response{topicDto(topicId)};
            if (path.endsWith("/stream_topics/" + secondTopicId)) return Response{topicDto(secondTopicId)};
            if (path.endsWith("/messages/") && request.method == "GET") {
                const QUrlQuery query(request.target);
                const auto quoteUuid = query.queryItemValue("uuid");
                if (!quoteUuid.isEmpty()) {
                    // Quote-lookup shape used by scheduleQuoteFetch:
                    // GET /messages/?project_id=&uuid= answered with a
                    // single-row array (docs/NATIVE_DESKTOP_REPLIES.md).
                    for (const auto &value : primary)
                        if (value.toObject().value("uuid").toString() == quoteUuid)
                            return Response{QJsonArray{value.toObject()}};
                    for (const auto &value : secondary)
                        if (value.toObject().value("uuid").toString() == quoteUuid)
                            return Response{QJsonArray{value.toObject()}};
                    return Response{QJsonArray{}};
                }
                const auto topic = query.queryItemValue("topic_uuid");
                if (topic == topicId) return Response{primary, 200, historyDelay};
                if (topic == secondTopicId) return Response{secondary};
                return Response{combined};
            }
            if (path.startsWith(filesPrefix)) {
                auto rest = path.mid(filesPrefix.size());
                const bool download = rest.endsWith(QLatin1String("/actions/download"));
                if (download) rest.chop(static_cast<int>(std::char_traits<char>::length("/actions/download")));
                if (!imageFiles.contains(rest)) return Response{QJsonObject{}, 404};
                if (!download) {
                    auto metadata = avatarProbeMetadata(rest, standalonePng);
                    metadata["stream_uuid"] = streamId;
                    metadata["name"] = rest == imageFiles.first() ? "photo.png" : "attachment.png";
                    return Response{metadata};
                }
                if (rest != imageFiles.first()) return Response{QJsonObject{}, 404};
                Response binary;
                binary.rawBody = standalonePng;
                binary.rawContentType = "image/png";
                return binary;
            }
            if (path.endsWith("/actions/read_up_to/invoke")) {
                if (historyDelay > 0) ++restoreReadPosts;
                for (const auto &value : primary) {
                    auto row = value.toObject();
                    if (path.contains("/messages/" + row.value("uuid").toString() + "/")) {
                        row["read"] = true;
                        return Response{row};
                    }
                }
                return Response{QJsonObject{}, 404};
            }
            if (request.method == "GET") {
                for (const auto &value : primary)
                    if (path.endsWith("/messages/" + value.toObject().value("uuid").toString()))
                        return Response{value.toObject()};
                for (const auto &value : secondary)
                    if (path.endsWith("/messages/" + value.toObject().value("uuid").toString()))
                        return Response{value.toObject()};
            }
            return sessionResponse(request);
        };
        QProcess process;
        const auto runChild = [&](const QString &phase, int timeoutMs) {
            auto environment = QProcessEnvironment::systemEnvironment();
            environment.insert(QStringLiteral("CASSI_NATIVE_LIVELOCK_CHILD_PHASE"), phase);
            environment.insert(QStringLiteral("CASSI_NATIVE_LIVELOCK_CHILD_ORIGIN"), server.origin().toString());
            environment.insert(QStringLiteral("CASSI_NATIVE_LIVELOCK_CHILD_ANCHOR"), anchor);
            environment.insert(QStringLiteral("CASSI_NATIVE_LIVELOCK_CHILD_CACHE"), cacheDir.path());
            process.setProcessEnvironment(environment);
            process.setProcessChannelMode(QProcess::MergedChannels);
            process.start(QCoreApplication::applicationFilePath(), {QStringLiteral("livelockPhase")});
            QVERIFY(process.waitForStarted(10000));
        };
        const auto pumpChild = [&](int timeoutMs, QString *out, bool *crashed) {
            // A GUI-thread livelock starves the child's own watchdog: silence IS
            // the reproduction, and QProcess' destructor ends the child on scope
            // exit. The parent keeps pumping so the mock server keeps serving.
            QElapsedTimer waited;
            waited.start();
            while (process.state() != QProcess::NotRunning && waited.elapsed() < timeoutMs)
                QTest::qWait(20);
            QVERIFY2(process.state() == QProcess::NotRunning,
                "freeze probe child stayed silent (livelock reproduction)");
            *out = QString::fromUtf8(process.readAll());
            *crashed = process.exitStatus() == QProcess::CrashExit;
        };
        // Issue #211 traced the isVisible crash to a test click retaining a
        // replaced sidebar delegate across its readiness wait. Resolve those
        // targets after the wait, but keep crashes distinct from the reported
        // livelock: a crashed child is relaunched once, a silent child still
        // fails as the reproduction, and a child that crashes twice fails too.
        const auto runMeasured = [&](const QString &phase, int timeoutMs, QString *out) {
            bool crashed = false;
            for (int attempt = 0; attempt < 2; ++attempt) {
                runChild(phase, timeoutMs);
                pumpChild(timeoutMs, out, &crashed);
                if (!crashed)
                    return;
            }
        };
        QString output;
        if (scenario == QStringLiteral("cache-restore")) {
            // The live report ran against an existing disk cache, so the frozen
            // presentation was the cached page followed by its revalidation
            // commit. Seed the cache in one child, then reproduce offline-first
            // with a delayed revalidation landing mid-monitor.
            QString seedOutput;
            bool seedCrashed = false;
            for (int attempt = 0; attempt < 2; ++attempt) {
                runChild(QStringLiteral("cache-seed"), 120000);
                pumpChild(120000, &seedOutput, &seedCrashed);
                if (!seedCrashed)
                    break;
            }
            QVERIFY2(seedOutput.contains(QStringLiteral("FREEZEPROBE seed")),
                "cache seeding child failed");
            QVERIFY2(process.exitStatus() == QProcess::NormalExit && process.exitCode() == 0,
                QStringLiteral("cache seeding child exited abnormally (status %1, crash %2)")
                    .arg(process.exitCode())
                    .arg(process.exitStatus() == QProcess::CrashExit ? 1 : 0)
                    .toUtf8().constData());
            historyDelay = 700;
            runMeasured(scenario, 120000, &output);
            QVERIFY2(restoreReadPosts > 0, "The restored conversation must send its visible read marker");
        } else {
            runMeasured(scenario, 120000, &output);
        }
        // The child prints its FREEZEPROBE line before the final verifications
        // of its own QtTest run (cache shutdown still follows the monitor), so
        // the report only counts once the child has exited the way a passing
        // QtTest run exits: normally, with status zero. A failure or crash
        // after reporting must fail this case (review follow-up on #141).
        QVERIFY2(process.exitStatus() == QProcess::NormalExit && process.exitCode() == 0,
            QStringLiteral("scenario=%1 freeze probe child exited abnormally (status %2, crash %3)\n%4")
                .arg(scenario).arg(process.exitCode())
                .arg(process.exitStatus() == QProcess::CrashExit ? 1 : 0)
                .arg(output)
                .toUtf8().constData());
        for (const auto &candidate : output.split(QLatin1Char('\n')))
            if (candidate.contains(QStringLiteral("FREEZEPROBE")))
                qDebug().noquote() << "freeze probe" << scenario << candidate;
        const QStringList problems = freezeProbeReportProblems(output);
        QVERIFY2(problems.isEmpty(), QStringLiteral("scenario=%1 freeze probe rejected the child reports\n%2\n%3")
            .arg(scenario, output, problems.join(QLatin1Char('\n'))).toUtf8().constData());
    }

    // The repeat-switch scenario opens three monitor windows (initial open +
    // two topic switches) and the child prints one FREEZEPROBE report per
    // window, but the parent-side parser historically consumed only the
    // first: a later window reporting a failed heartbeat or settle check
    // would pass the case silently (exordos review on #141). Drive the exact
    // parser the parent uses with synthetic reports — forcing a scene-level
    // injection that breaks only a later monitor window is not practical.
    void freezeProbeParentConsumesAllMonitorReports()
    {
        const QString good = QStringLiteral(
            "FREEZEPROBE phase=repeat-switch settled=1 settleMs=840 unstable=6 lateMoves=0 ticks=178 maxRssKib=262144");
        // A single healthy report passes; an output with no report does not.
        QVERIFY(freezeProbeReportProblems(good).isEmpty());
        QVERIFY(!freezeProbeReportProblems(QStringLiteral("PASS : NativeLivelockWindowWorker::livelockPhase()")).isEmpty());

        // Second of three windows never stays settled to the end.
        QVERIFY(!freezeProbeReportProblems(QStringList{
            good,
            QStringLiteral("FREEZEPROBE phase=repeat-switch settled=0 settleMs=840 unstable=38 lateMoves=12 ticks=161 maxRssKib=262144"),
            good}.join(QLatin1Char('\n'))).isEmpty());

        // Third window's event-loop heartbeat starves after the switch back.
        QVERIFY(!freezeProbeReportProblems(QStringList{
            good, good,
            QStringLiteral("FREEZEPROBE phase=repeat-switch settled=1 settleMs=840 unstable=6 lateMoves=0 ticks=7 maxRssKib=262144")}
            .join(QLatin1Char('\n'))).isEmpty());

        // Third window blows the memory budget during the switch back.
        QVERIFY(!freezeProbeReportProblems(QStringList{
            good, good,
            QStringLiteral("FREEZEPROBE phase=repeat-switch settled=1 settleMs=840 unstable=6 lateMoves=0 ticks=178 maxRssKib=1610612736")}
            .join(QLatin1Char('\n'))).isEmpty());

        // Second window settles only after the 5s budget.
        QVERIFY(!freezeProbeReportProblems(QStringList{
            good,
            QStringLiteral("FREEZEPROBE phase=repeat-switch settled=1 settleMs=6900 unstable=6 lateMoves=0 ticks=178 maxRssKib=262144"),
            good}.join(QLatin1Char('\n'))).isEmpty());
    }

    // ---- Issue #83: real folder rail scopes the sidebar (docs/NATIVE_DESKTOP_FOLDERS_RAIL.md) ----
    void folderRailRendersServerFoldersAndScopesTheSidebar()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const QString folderStreamB = QStringLiteral("8e8e8e8e-8e8e-4e8e-8e8e-8e8e8e8e8e8e");
        const QString folderFocus = QStringLiteral("9f9f9f9f-9f9f-4f9f-8f9f-9f9f9f9f9f9f");
        MockServer server;
        server.handler = [&](const Request &request) -> Response {
            const auto path = request.target.path();
            if (path.endsWith("/messenger/folders/"))
                return {QJsonArray{
                    QJsonObject{{"uuid","00000000-0000-0000-0000-000000000000"},{"title","All chats"},
                        {"system_type","all"},{"unread_count",0},{"background_color_value",0}},
                    QJsonObject{{"uuid","00000000-0000-0000-0000-000000000001"},{"title","Personal"},
                        {"system_type","personal"},{"unread_count",0},{"background_color_value",0}},
                    QJsonObject{{"uuid","00000000-0000-0000-0000-000000000002"},{"title","Channels"},
                        {"system_type","channels"},{"unread_count",0},{"background_color_value",0}},
                    QJsonObject{{"uuid",folderFocus},{"title","Focus"},{"system_type","created"},
                        {"unread_count",7},{"background_color_value",0x2563eb},
                        {"folder_items",QJsonArray{QJsonObject{{"uuid","fi-b"},{"stream_uuid",folderStreamB},
                            {"chat_type","channel"}}}}}}};
            if (path.endsWith("/messenger/streams/"))
                return {QJsonArray{windowChannel(streamId,"Alpha"), windowChannel(folderStreamB,"Beta")}};
            if (path == "/api/workspace/v1/messenger/streams/"+streamId) return {windowChannel(streamId,"Alpha")};
            if (path == "/api/workspace/v1/messenger/streams/"+folderStreamB) return {windowChannel(folderStreamB,"Beta")};
            if (path.endsWith("/messenger/stream_topics/")) return {QJsonArray{}};
            if (path.endsWith("/users/")) return {QJsonArray{QJsonObject{{"uuid",userId},{"username","cassi"}}}};
            if (path.contains("/messages/")) return {QJsonArray{}};
            return sessionResponse(request);
        };
        ApiClient api(nullptr,true); Session session(&api); NativeController controller(&api,&session);
        NativePreferences preferences(directory.filePath("preferences.ini"));
        QQmlApplicationEngine engine; loadNativeUi(engine,&controller,&preferences);
        auto *window=qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close=qScopeGuard([&engine,guard=QPointer<QQuickWindow>(window)]{
            if(guard&&!closeIncubatedTestWindow(engine,guard.data()))QTest::qFail("Folders rail teardown",__FILE__,__LINE__);});
        QVERIFY(QTest::qWaitForWindowExposed(window)); window->requestActivate(); QVERIFY(QTest::qWaitForWindowActive(window));
        controller.login(server.origin().toString(),"synthetic-user","synthetic-password","");
        QTRY_COMPARE_WITH_TIMEOUT(controller.projects().size(),1,2000);
        controller.openProject(projectId);
        QTRY_COMPARE_WITH_TIMEOUT(controller.streams().size(),2,2000);
        // All four rail cells render; the static disabled placeholders are gone.
        QTRY_VERIFY_WITH_TIMEOUT(visibleItem("folder-all") && visibleItem("folder-personal")
            && visibleItem("folder-channels") && visibleItem("folder-"+folderFocus), 5000);
        auto *all=visibleItem("folder-all"); QVERIFY(all);
        auto *personal=visibleItem("folder-personal"); QVERIFY(personal);
        auto *channels=visibleItem("folder-channels"); QVERIFY(channels);
        auto *focus=visibleItem("folder-"+folderFocus); QVERIFY(focus);
        QVERIFY(personal->property("enabled").toBool());
        QVERIFY(channels->property("enabled").toBool());
        for(auto *object:window->findChildren<QObject *>())
            QVERIFY(object->property("help").toString()!="This filter is not implemented yet");
        // The All slot is pinned above the scrollable group (async delegate
        // incubation: give the layout one settle window).
        const auto sceneY=[&](QQuickItem *entry){return entry->mapToScene(QPointF(0,0)).y();};
        QTRY_VERIFY_WITH_TIMEOUT(sceneY(all)<sceneY(personal) && sceneY(personal)<sceneY(channels)
            && sceneY(channels)<sceneY(focus), 5000);
        // The custom folder carries the unread badge (7) and its folder color.
        auto *badge=visibleItem("folderBadge-"+folderFocus); QVERIFY(badge);
        QCOMPARE(badge->property("text").toString(),QStringLiteral("7"));
        // An active sidebar search hides Beta until the folder scopes it away.
        window->setProperty("sidebarQuery","alph");
        QTRY_VERIFY_WITH_TIMEOUT(visibleItem("stream-"+streamId) && !visibleItem("stream-"+folderStreamB), 2000);
        // Selecting the custom folder clears the search and scopes the list.
        click(window,focus);
        QTRY_COMPARE(window->property("sidebarQuery").toString(),QString());
        QTRY_COMPARE(controller.selectedFolder(),folderFocus);
        QTRY_VERIFY_WITH_TIMEOUT(!visibleItem("stream-"+streamId) && visibleItem("stream-"+folderStreamB), 2000);
        // The selected card scales 1.1; All goes back to 1.0.
        auto *focusCard=item(window->contentItem(),"folderCard-"+folderFocus); QVERIFY(focusCard);
        QTRY_COMPARE(focusCard->property("scale").toReal(),qreal(1.1));
        auto *allCard=item(window->contentItem(),"folderCard-all"); QVERIFY(allCard);
        QTRY_COMPARE(allCard->property("scale").toReal(),qreal(1.0));
        // Selecting All again restores the full list.
        click(window,visibleItem("folder-all"));
        QTRY_COMPARE(controller.selectedFolder(),QStringLiteral("00000000-0000-0000-0000-000000000000"));
        QTRY_VERIFY(visibleItem("stream-"+streamId));
        QTRY_VERIFY(visibleItem("stream-"+folderStreamB));
        // The add-folder button is enabled chrome (the creation flow is issue #84).
        auto *add=visibleItem("folderAddButton"); QVERIFY(add);
        QVERIFY(add->property("enabled").toBool());
    }

    void durableOutgoingActualMainRetriesAndDiscards_data()
    {
        QTest::addColumn<QString>("locale"); QTest::addColumn<QString>("mode");
        for (const auto *locale : {"en", "ru"}) for (const auto *mode : {"light", "dark"})
            QTest::addRow("%s-%s", locale, mode) << QString(locale) << QString(mode);
    }
    void durableOutgoingActualMainRetriesAndDiscards()
    {
        QFETCH(QString, locale); QFETCH(QString, mode);
        QTemporaryDir directory; WindowDraftFixture fixture;
        QVector<QJsonObject> posts; QStringList requests; QJsonObject saved; bool complete = false;
        const auto fallback = fixture.server.handler;
        fixture.server.handler = [&](const Request &request) -> Response {
            const auto path = request.target.path();
            if (path.contains("/messenger/messages/")) {
                if (request.method == "POST") {
                    posts.append(request.body); requests.append("POST");
                    const auto placement = QUuid::createUuidV5(QUuid(topicId), request.body.value("uuid").toString().toUtf8()).toString(QUuid::WithoutBraces);
                    saved = message(request.body.value("payload").toObject().value("content").toString(), placement);
                    return complete ? Response{saved} : Response{QJsonObject{}, 503};
                }
                if (!path.endsWith('/')) {
                    requests.append("GET"); return complete && posts.size() == 2 ? Response{saved} : Response{QJsonObject{}, 404};
                }
                return {QJsonArray{}};
            }
            return fallback(request);
        };
        NativeDraftService storage(directory.filePath("drafts")); NativeDrafts drafts(&storage);
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session); controller.useDrafts(&drafts);
        NativePreferences preferences(directory.filePath("preferences.ini")); preferences.setLocale(locale); preferences.setMode(mode);
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] { if (guard) closeIncubatedTestWindow(engine, guard.data()); });
        QVERIFY(QTest::qWaitForWindowExposed(window)); window->requestActivate(); QVERIFY(QTest::qWaitForWindowActive(window));
        QVERIFY(startComposerEmojiFixture(fixture, controller, session)); QTRY_VERIFY(drafts.ready(streamId, topicId));
        const auto view = [&](const QString &name) { return visibleItem(window->contentItem(), name); };
        controller.setDraft("Durable outgoing original"); QTRY_VERIFY(controller.canSend()); click(window, view("sendButton"));
        QTRY_COMPARE(posts.size(), 1); QTRY_VERIFY(!controller.busy()); QTRY_VERIFY(view("pendingOutgoingStatus"));
        QVERIFY(!view("sendButton")->isEnabled()); QVERIFY(view("retryPendingOutgoingButton")->isEnabled());
        QCOMPARE(view("retryPendingOutgoingButton")->property("text").toString(), locale == "ru" ? QString("Повторить") : QString("Retry"));
        auto *composer = view("messageComposer"); QVERIFY(composer); composer->forceActiveFocus();
        QTest::keyClick(window, Qt::Key_A, Qt::ControlModifier);
        QInputMethodEvent edited; edited.setCommitString("Newer draft survives retry"); QCoreApplication::sendEvent(composer, &edited);
        QTRY_COMPARE(controller.draft(), "Newer draft survives retry");
        const auto captures = qEnvironmentVariable("CASSI_OUTGOING_SCREENSHOTS");
        if (!captures.isEmpty()) QVERIFY(window->grabWindow().save(QDir(captures).filePath(locale + "-" + mode + "-pending.png")));
        complete = true; click(window, view("retryPendingOutgoingButton")); QTRY_COMPARE(posts.size(), 2);
        QTRY_VERIFY(controller.outgoingSend().isEmpty()); QCOMPARE(posts[0], posts[1]);
        QCOMPARE(requests, QStringList({"POST", "GET", "POST", "GET"})); QCOMPARE(controller.draft(), "Newer draft survives retry");
        complete = false; QTRY_VERIFY(controller.canSend()); click(window, view("sendButton"));
        QTRY_COMPARE(posts.size(), 3); QTRY_VERIFY(!controller.busy());
        auto *list = view("messageList"); QVERIFY(list);
        QTRY_VERIFY(list->property("readActive").toBool());
        click(window, view("discardPendingOutgoingButton"));
        auto *dialog = window->findChild<QObject *>("discardPendingOutgoingDialog"); QVERIFY(dialog); QTRY_VERIFY(dialog->property("visible").toBool());
        QVERIFY(!list->property("readActive").toBool());
        QTest::keyClick(window, Qt::Key_Escape); QTRY_VERIFY(!dialog->property("visible").toBool()); QVERIFY(!controller.outgoingSend().isEmpty());
        QTRY_VERIFY(list->property("readActive").toBool());
        click(window, view("discardPendingOutgoingButton")); QTRY_VERIFY(dialog->property("visible").toBool());
        QQmlExpression discardButton(qmlContext(dialog), dialog, "standardButton(8388608)"); // Dialog.Discard
        auto *discard = qobject_cast<QQuickItem *>(discardButton.evaluate().value<QObject *>());
        QVERIFY(!discardButton.hasError()); QVERIFY(discard); click(window, discard);
        QTRY_VERIFY(controller.outgoingSend().isEmpty());
        QCOMPARE(controller.draft(), "Newer draft survives retry"); QCOMPARE(posts.size(), 3);
        QVERIFY(closeIncubatedTestWindow(engine, window)); close.dismiss();
    }

