    // exordy review PRRT_kwDOVmpjls65Qz-2: the process table columns total
    // 408 px (96+64+96+96+56 min) and the old flexible CPU column pushed the
    // header/rows past the panel width with no way to reach the clipped cells.
    // The table must live in a horizontal Flickable whose contentWidth exposes
    // every column, with the rows sized to that content width, never wider.
    void diagnosticsMemoryPanelTableScrollsHorizontallyWithoutOverflow()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const auto proc = directory.filePath("proc");
        QVERIFY(QDir(proc).mkpath(QStringLiteral("self")));
        const auto writeProc=[&](const QString &name, const QByteArray &body){
            QFile file(proc + name); QVERIFY(file.open(QIODevice::WriteOnly));
            file.write(body); };
        writeProc(QStringLiteral("/self/status"), QByteArrayLiteral(
            "Name:\tworkspace-native\nPid:\t4242\nVmSize:\t   20480 kB\n"
            "VmHWM:\t   9216 kB\nVmRSS:\t   8192 kB\nThreads:\t7\n"));
        writeProc(QStringLiteral("/meminfo"), QByteArrayLiteral(
            "MemTotal:        8388608 kB\nMemFree:          524288 kB\n"
            "MemAvailable:    4194304 kB\n"));
        ApiClient api(nullptr,true); Session session(&api); NativeController controller(&api,&session);
        controller.setDiagnosticsMemoryProcRoot(proc);
        NativePreferences preferences(directory.filePath("preferences.ini"));
        preferences.setLocale("en"); preferences.setMode("light");
        WindowOwnStatusFixture fixture; QVERIFY(fixture.start(controller));
        QQmlApplicationEngine engine; loadNativeUi(engine,&controller,&preferences);
        auto *window=qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close=qScopeGuard([&engine,guard=QPointer<QQuickWindow>(window)]{
            if(guard&&!closeIncubatedTestWindow(engine,guard.data()))QTest::qFail("Table scroller teardown",__FILE__,__LINE__);});
        QVERIFY(QTest::qWaitForWindowExposed(window));
        click(window, visibleItem("accountMenuButton"));
        QTRY_VERIFY_WITH_TIMEOUT(visibleItem("diagnosticsAction"), 4000);
        click(window, visibleItem("diagnosticsAction"));
        QTRY_VERIFY_WITH_TIMEOUT(controller.section()==QStringLiteral("diagnostics"), 4000);
        auto *scroller=visibleItem("diagnosticsMemoryTableScroller");
        QVERIFY2(scroller, "process table needs a horizontal Flickable (diagnosticsMemoryTableScroller)");
        QVERIFY2(scroller->clip(), "the table scroller must clip to the panel width");
        auto *scrollerParent=scroller->parentItem(); QVERIFY(scrollerParent);
        QVERIFY2(scroller->width() <= scrollerParent->width() + 1.0,
                 qPrintable(QStringLiteral("scroller %1 px wider than its panel column %2 px")
                     .arg(scroller->width()).arg(scrollerParent->width())));
        // Sum the header column widths: every column must fit inside the
        // scrollable content width (clipped cells are reachable by scrolling).
        auto *header=visibleItem("diagnosticsMemoryTableHeader"); QVERIFY(header);
        const qreal contentWidth=scroller->property("contentWidth").toReal();
        QVERIFY2(contentWidth >= 408.0,
                 qPrintable(QStringLiteral("contentWidth %1 below the 408 px column floor").arg(contentWidth)));
        qreal columns=0.0;
        for (const char *key : {"type", "pid", "workingSet", "peak", "cpu"}) {
            auto *cell=header->findChild<QQuickItem*>(
                QStringLiteral("diagnosticsMemoryTableHeader-%1").arg(QLatin1String(key)));
            QVERIFY2(cell, QStringLiteral("missing header column %1").arg(QLatin1String(key)).toUtf8().constData());
            columns += cell->width();
        }
        QVERIFY2(columns <= contentWidth + 1.0,
                 qPrintable(QStringLiteral("columns %1 px exceed scrollable content %2 px")
                     .arg(columns).arg(contentWidth)));
        // The data row is sized to the scrollable content, never beyond it.
        auto *row=visibleItem("diagnosticsMemoryProcessRow-0"); QVERIFY(row);
        QVERIFY2(row->width() <= contentWidth + 1.0,
                 qPrintable(QStringLiteral("row %1 px wider than content %2 px")
                     .arg(row->width()).arg(contentWidth)));
    }

    // Review 4611502344 on #404: an API-generation change (token loss,
    // account/server switch) drops the in-flight ping callback, so the page
    // used to sit in loading forever. The bump must settle the ping as a
    // failed probe and the button must become usable again.
    void diagnosticsPingSettlesAcrossApiGenerationChange()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        ApiClient api(nullptr,true); Session session(&api); NativeController controller(&api,&session);
        NativePreferences preferences(directory.filePath("preferences.ini"));
        preferences.setLocale("en"); preferences.setMode("light");
        int pingGets=0; bool holdPing=true; std::function<void()> release;
        WindowOwnStatusFixture fixture;
        const auto baseHandler=fixture.server.handler;
        fixture.server.handler=[&](const Request &request)->Response{
            if(request.target.path()==QStringLiteral("/api/workspace/v1/messenger/streams/")
               && QUrlQuery(request.target).queryItemValue("page_limit")==QStringLiteral("1")){
                ++pingGets;
                Response response{QJsonArray{}};
                if(holdPing)response.defer=[&](std::function<void()> send){release=std::move(send);};
                return response;
            }
            return baseHandler(request);
        };
        QVERIFY(fixture.start(controller));
        QQmlApplicationEngine engine; loadNativeUi(engine,&controller,&preferences);
        auto *window=qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close=qScopeGuard([&engine,guard=QPointer<QQuickWindow>(window)]{
            if(guard&&!closeIncubatedTestWindow(engine,guard.data()))QTest::qFail("Diagnostics page teardown",__FILE__,__LINE__);});
        auto drop=qScopeGuard([&release]{if(release)release();});
        QVERIFY(QTest::qWaitForWindowExposed(window));
        click(window, visibleItem("accountMenuButton"));
        QTRY_VERIFY_WITH_TIMEOUT(visibleItem("diagnosticsAction"), 4000);
        click(window, visibleItem("diagnosticsAction"));
        QTRY_VERIFY_WITH_TIMEOUT(controller.section()==QStringLiteral("diagnostics"), 4000);
        auto *page=visibleItem("nativeDiagnosticsPage"); QVERIFY(page);
        QSignalSpy finished(&controller, &NativeController::pingFinished);
        click(window, visibleItem("diagnosticsPingButton"));
        QCOMPARE(page->property("pingState").toString(), QString("loading"));
        QVERIFY(QTest::qWaitFor([&]{return pingGets==1;},2000));
        QCOMPARE(finished.count(), 0); // the answer is held by the gate
        api.clearSession(); // token/account boundary: the bump retires the callback
        // The page must leave loading on the bump, not wait for a callback
        // that can never arrive.
        QCOMPARE(page->property("pingState").toString(), QString("error"));
        QCOMPARE(finished.count(), 1);
        QCOMPARE(visibleItem("diagnosticsPingLabel")->property("text").toString(), QString("Unreachable"));
        api.setAccessToken("rotated-token"); // a credential under the new generation so the probe really dispatches
        holdPing=false; // the next ping answers immediately
        click(window, visibleItem("diagnosticsPingButton")); // not stuck: usable again
        QCOMPARE(page->property("pingState").toString(), QString("loading"));
        QVERIFY(finished.wait(5000));
        QCOMPARE(finished.count(), 2);
        QCOMPARE(page->property("pingState").toString(), QString("success"));
    }

    // Review 4611502346 on #404: starting a ping while the previous ping's
    // feedback reset is pending let the stale timer clear the new ping's
    // loading state mid-flight (button re-enabled while still in flight).
    // A new ping must cancel the pending reset first.
    void diagnosticsNewPingCancelsPendingFeedbackReset()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        ApiClient api(nullptr,true); Session session(&api); NativeController controller(&api,&session);
        NativePreferences preferences(directory.filePath("preferences.ini"));
        preferences.setLocale("en"); preferences.setMode("light");
        int pingGets=0; bool holdPing=false; std::function<void()> release;
        WindowOwnStatusFixture fixture;
        const auto baseHandler=fixture.server.handler;
        fixture.server.handler=[&](const Request &request)->Response{
            if(request.target.path()==QStringLiteral("/api/workspace/v1/messenger/streams/")
               && QUrlQuery(request.target).queryItemValue("page_limit")==QStringLiteral("1")){
                ++pingGets;
                Response response{QJsonArray{}};
                if(holdPing)response.defer=[&](std::function<void()> send){release=std::move(send);};
                return response;
            }
            return baseHandler(request);
        };
        QVERIFY(fixture.start(controller));
        QQmlApplicationEngine engine; loadNativeUi(engine,&controller,&preferences);
        auto *window=qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close=qScopeGuard([&engine,guard=QPointer<QQuickWindow>(window)]{
            if(guard&&!closeIncubatedTestWindow(engine,guard.data()))QTest::qFail("Diagnostics page teardown",__FILE__,__LINE__);});
        auto drop=qScopeGuard([&release]{if(release)release();});
        QVERIFY(QTest::qWaitForWindowExposed(window));
        click(window, visibleItem("accountMenuButton"));
        QTRY_VERIFY_WITH_TIMEOUT(visibleItem("diagnosticsAction"), 4000);
        click(window, visibleItem("diagnosticsAction"));
        QTRY_VERIFY_WITH_TIMEOUT(controller.section()==QStringLiteral("diagnostics"), 4000);
        auto *page=visibleItem("nativeDiagnosticsPage"); QVERIFY(page);
        QSignalSpy finished(&controller, &NativeController::pingFinished);
        // First ping: answered immediately, so the 3 s feedback timer is now
        // pending while the second ping is dispatched.
        click(window, visibleItem("diagnosticsPingButton"));
        QVERIFY(finished.wait(5000));
        QCOMPARE(page->property("pingState").toString(), QString("success"));
        holdPing=true;
        click(window, visibleItem("diagnosticsPingButton")); // click during feedback
        QCOMPARE(page->property("pingState").toString(), QString("loading"));
        QVERIFY(QTest::qWaitFor([&]{return pingGets==2;},2000));
        // Wait out the first ping's reset deadline (3 s from its answer).
        // The stale timer must not have settled the second ping early.
        QTest::qWait(page->property("pingFeedbackMs").toInt()+400);
        QCOMPARE(page->property("pingState").toString(), QString("loading"));
        QCOMPARE(finished.count(), 1);
        release(); // the second ping lands now
        QVERIFY(finished.wait(5000));
        QCOMPARE(page->property("pingState").toString(), QString("success"));
    }

    // ---- Favorites self-chat (#70, docs/NATIVE_DESKTOP_FAVORITES_SELF_CHAT.md) ----

    // The enabled Favorites chip opens the "Personal notes" self-chat with
    // the favorites header presentation, the composer behaves as in a normal
    // DM, the right drawer is forced closed (chat-page.ui.tsx:40-42), and
    // the self stream stays out of the ordinary sidebar list
    // (messenger-sidebar.lib.ts:560,592,616,656).
    void favoritesChipOpensSelfChatConversation()
    {
        WindowFavoritesFixture fixture;
        fixture.catalogIncludesSelf = true;
        fixture.sourceScene = true; // startComposerEmojiFixture needs the 3-topic scene
        QTemporaryDir directory; QVERIFY(directory.isValid());
        NativePreferences preferences(directory.filePath("p.ini"));
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard) closeIncubatedTestWindow(engine, guard.data());
        });
        QVERIFY(QTest::qWaitForWindowExposed(window)); window->requestActivate();
        QVERIFY(startComposerEmojiFixture(fixture, controller, session));
        const auto view = [&](const QString &name) { return visibleItem(window->contentItem(), name); };
        // The ordinary sidebar shows the normal channel but never the self
        // stream; Favorites is its only entry point.
        QVERIFY(view("stream-" + streamId));
        QVERIFY(!view("stream-" + windowFavoritesStream));
        // The right drawer is open first so the favorites mount can force it
        // closed, exactly like the reference effect on route mount.
        QMetaObject::invokeMethod(item(window->contentItem(), "nativeRightDrawer"), "toggleChatInfo");
        QTRY_VERIFY_WITH_TIMEOUT(visibleItem("nativeRightDrawer"), 4000);
        auto *chip = view("activity-favorites"); QVERIFY(chip && chip->isEnabled());
        click(window, chip);
        QVERIFY(controller.favoritesVisible());
        // The catalog already carried the self stream: no create request.
        QTRY_VERIFY_WITH_TIMEOUT(controller.favoritesStatus() == QStringLiteral("ready"), 5000);
        QCOMPARE(fixture.selfPosts, 0);
        QCOMPARE(fixture.selfPostBody, QJsonObject{});
        QCOMPARE(controller.selectedStream(), windowFavoritesStream);
        QCOMPARE(controller.selectedTopic(), windowFavoritesTopic);
        // The favorites header replaces the ordinary title...
        QTRY_VERIFY(view("favoritesConversationHeader"));
        QCOMPARE(view("favoritesConversationHeader")->property("text").toString(), QString("Favorites"));
        QVERIFY(!visibleItem("favoritesStateHeader")); // the state page is not shown when ready
        // ...and the right drawer left with the favorites mount.
        QTRY_VERIFY_WITH_TIMEOUT(!item(window->contentItem(), "nativeRightDrawer")->isVisible(), 4000);
        // The self note renders and the composer behaves like a normal DM:
        // text, send, verified read-back bubble.
        QTRY_VERIFY(view("message-content-" + windowFavoritesNote));
        auto *composer = item(window->contentItem(), "messageComposer");
        QVERIFY(composer && composer->isVisible() && composer->isEnabled());
        composer->setProperty("text", "A note written through Favorites.");
        QTRY_VERIFY_WITH_TIMEOUT(controller.canSend(), 4000);
        click(window, item(window->contentItem(), "sendButton"));
        QTRY_VERIFY_WITH_TIMEOUT(fixture.selfPostBody == QJsonObject{} && fixture.sentEcho.contains("uuid"), 6000);
        QTRY_VERIFY_WITH_TIMEOUT(view("message-content-" + windowFavoritesSent), 6000);
        // The self stream still never appears in the ordinary list, and the
        // re-clicked chip keeps the ready conversation (no re-route, no POST).
        QVERIFY(!view("stream-" + windowFavoritesStream));
        click(window, view("activity-favorites"));
        QVERIFY(controller.favoritesVisible());
        QCOMPARE(controller.favoritesStatus(), QStringLiteral("ready"));
        QCOMPARE(fixture.selfPosts, 0);
        // Selecting an ordinary stream leaves the favorites presentation.
        click(window, view("stream-" + streamId));
        QTRY_VERIFY_WITH_TIMEOUT(!controller.favoritesVisible(), 4000);
        QVERIFY(controller.selectedStream() == streamId);
    }

    void favoritesTopicCompletionFollowsCurrentPage_data()
    {
        QTest::addColumn<QString>("scenario");
        for (const auto *name : {"calendar", "reopened", "http-failure", "transport-failure", "malformed"})
            QTest::newRow(name) << QString::fromLatin1(name);
    }

    void favoritesTopicCompletionFollowsCurrentPage()
    {
        QFETCH(QString, scenario);
        WindowFavoritesFixture fixture;
        fixture.catalogIncludesSelf = true;
        fixture.sourceScene = true;
        int topicRequests = 0;
        bool recovered = false;
        std::function<void()> release;
        const auto fallback = fixture.server.handler;
        fixture.server.handler = [&](const Request &request) {
            auto reply = fallback(request);
            if (!request.target.path().endsWith("/stream_topics/")
                || QUrlQuery(request.target).queryItemValue("stream_uuid") != windowFavoritesStream)
                return reply;
            if (++topicRequests == 1) {
                if (scenario == "http-failure" || scenario == "reopened") reply.status = 500;
                if (scenario == "transport-failure") reply.abortConnection = true;
                if (scenario == "malformed") reply.data = QJsonArray{QJsonObject{}};
                reply.headers.insert("X-Favorites-Test", "held");
                reply.defer = [&](std::function<void()> deliver) { release = std::move(deliver); };
            } else if (scenario == "transport-failure" && !recovered) {
                // Qt may transparently retry a GET after the first connection closes.
                reply.abortConnection = true;
            }
            return reply;
        };
        QTemporaryDir directory;
        NativePreferences preferences(directory.filePath("prefs.ini"));
        ApiClient api(nullptr, true);
        Session session(&api);
        NativeController controller(&api, &session);
        QQmlApplicationEngine engine;
        loadNativeUi(engine, &controller, &preferences);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0));
        QVERIFY(window);
        auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard) closeIncubatedTestWindow(engine, guard.data());
        });
        QVERIFY(QTest::qWaitForWindowExposed(window));
        QVERIFY(startComposerEmojiFixture(fixture, controller, session));
        const auto view = [&](const QString &name) { return visibleItem(window->contentItem(), name); };
        auto *chip = view("activity-favorites");
        QVERIFY(chip);
        click(window, chip);
        QTRY_VERIFY(release);
        QCOMPARE(controller.favoritesStatus(), "loading");
        if (scenario == "calendar" || scenario == "reopened") {
            auto *calendar = view("sectionCalendarButton");
            QVERIFY(calendar);
            click(window, calendar);
            QTRY_COMPARE(controller.section(), "calendar");
            QVERIFY(!controller.favoritesVisible());
            if (scenario == "reopened") {
                click(window, view("sectionChatButton"));
                QTRY_VERIFY(view("activity-favorites"));
                click(window, view("activity-favorites"));
                QTRY_COMPARE(controller.favoritesStatus(), "ready");
            }
            auto *network = api.findChild<QNetworkAccessManager *>();
            QVERIFY(network);
            bool completed = false;
            auto connection = connect(network, &QNetworkAccessManager::finished, this, [&](QNetworkReply *reply) {
                if (reply->rawHeader("X-Favorites-Test") == "held") completed = true;
            });
            auto disconnectFinished = qScopeGuard([&] { disconnect(connection); });
            release();
            QTRY_VERIFY(completed);
            if (scenario == "calendar") {
                QCOMPARE(controller.section(), "calendar");
                QVERIFY(!controller.favoritesVisible());
                QVERIFY(controller.selectedTopic() != windowFavoritesTopic);
            } else {
                QCOMPARE(controller.favoritesStatus(), "ready");
                QCOMPARE(controller.selectedTopic(), windowFavoritesTopic);
            }
        } else {
            release();
            QTRY_VERIFY_WITH_TIMEOUT(view("favoritesRetryButton"), 2500);
            QVERIFY(!view("favoritesLoading"));
            QCOMPARE(controller.favoritesStatus(), "error");
            recovered = true;
            auto *retry = view("favoritesRetryButton");
            click(window, retry);
            QTRY_COMPARE(controller.selectedTopic(), windowFavoritesTopic);
            QCOMPARE(controller.favoritesStatus(), "ready");
            QTRY_VERIFY(view("favoritesConversationHeader"));
        }
        QCOMPARE(fixture.selfPosts, 0);
    }

