    // #62 round 3 (review thread cid 4609403368): the pending-gate re-capture
    // in saveWindow also accepted WindowNoState while the WM hop is still in
    // flight, so a quit/detach save landing mid-hop persisted the transition
    // geometry and cleared the settled maximized flag. Both cases latch onto
    // the WindowNoState emission of the documented hop and detach synchronously
    // inside it - that is exactly the instant a aboutToQuit/detach save races.
    // Entering fullscreen from maximized: the WM unmaximizes (WindowNoState at
    // the work-area geometry) before placing fullscreen, so the transient also
    // fills the screen while the target state has not been reached.
    void fullscreenEnterMidTransitionSaveKeepsSettledMaximizedState()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const auto path = directory.filePath("preferences.ini");
        NativePreferences preferences(path);
        QWindow window;
        auto teardown = qScopeGuard([&preferences, &window] {
            preferences.attachWindow(nullptr);
            window.close();
        });
        preferences.attachWindow(&window);
        window.show(); QVERIFY(QTest::qWaitForWindowExposed(&window));
        const auto available = QGuiApplication::primaryScreen()->availableGeometry();
        const QRect normal(available.x() + 60, available.y() + 40, 880, 620);
        window.setGeometry(normal);
        QTest::qWait(700);
        window.showMaximized();
        QTRY_COMPARE_WITH_TIMEOUT(window.windowState(), Qt::WindowMaximized, 5000);
        QTest::qWait(700); // settled: normal bounds + maximized=true are on disk
        QVERIFY(QSettings(path, QSettings::IniFormat).value("window/maximized").toBool());
        QCOMPARE(savedWindowBounds(path), normal);
        bool armed = false;
        bool savedMidHop = false;
        const auto conn = connect(&window, &QWindow::windowStateChanged, &preferences,
            [&preferences, &armed, &savedMidHop](Qt::WindowState state) {
                if (!armed || state != Qt::WindowNoState || savedMidHop) return;
                savedMidHop = true;
                preferences.attachWindow(nullptr); // the aboutToQuit seam: immediate save
            });
        // openbox sometimes coalesces the unmaximize hop with the fullscreen
        // placement into a single state update, so retry the toggle cycle a
        // few times and only arm the latch for the enter direction (same WM
        // race retry pattern as activationRestores... above).
        bool exercised = false;
        for (int attempt = 0; attempt < 5 && !exercised; ++attempt) {
            savedMidHop = false;
            QTest::keyClick(&window, Qt::Key_F11);
            armed = true;
            if (QTest::qWaitFor([&] { return savedMidHop; }, 1200)) {
                exercised = true;
                break;
            }
            armed = false;
            // No hop this attempt: finish entering and exiting so the next
            // attempt starts maximized again with the gate released.
            QTRY_VERIFY_WITH_TIMEOUT(window.visibility() == QWindow::FullScreen, 3000);
            QTest::keyClick(&window, Qt::Key_F11);
            QTRY_COMPARE_WITH_TIMEOUT(window.windowState(), Qt::WindowMaximized, 3000);
            QTest::qWait(500);
        }
        disconnect(conn);
        if (!exercised)
            QSKIP("the WM never emitted the unmaximize hop this run");
        const QSettings mid(path, QSettings::IniFormat);
        QVERIFY2(mid.value("window/maximized").toBool(),
            "the mid-transition save persisted the transient hop and cleared the maximized flag");
        QCOMPARE(savedWindowBounds(path), normal);
    }

    // Exiting fullscreen to normal: the state change lands before the WM has
    // configured the window back to its normal geometry, so a save inside the
    // WindowNoState emission still sees the fullscreen rectangle. The persisted
    // normal bounds must stay the settled ones, not the transition rectangle.
    void fullscreenExitMidTransitionSaveKeepsSavedNormalBounds()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const auto path = directory.filePath("preferences.ini");
        NativePreferences preferences(path);
        QWindow window;
        auto teardown = qScopeGuard([&preferences, &window] {
            preferences.attachWindow(nullptr);
            window.close();
        });
        preferences.attachWindow(&window);
        window.show(); QVERIFY(QTest::qWaitForWindowExposed(&window));
        const auto available = QGuiApplication::primaryScreen()->availableGeometry();
        const QRect normal(available.x() + 45, available.y() + 35, 860, 640);
        window.setGeometry(normal);
        QTest::qWait(700);
        QTest::keyClick(&window, Qt::Key_F11);
        QTRY_VERIFY_WITH_TIMEOUT(window.visibility() == QWindow::FullScreen, 5000);
        QTest::qWait(700); // let the enter gate settle before starting the exit
        QVERIFY(savedWindowBounds(path) == normal);
        bool savedMidHop = false;
        const auto conn = connect(&window, &QWindow::windowStateChanged, &preferences,
            [&preferences, &savedMidHop](Qt::WindowState state) {
                if (state != Qt::WindowNoState || savedMidHop) return;
                savedMidHop = true;
                preferences.attachWindow(nullptr); // the aboutToQuit seam: immediate save
            });
        QTest::keyClick(&window, Qt::Key_F11);
        QTRY_VERIFY_WITH_TIMEOUT(savedMidHop, 5000); // the WM hop must emit WindowNoState
        disconnect(conn);
        QCOMPARE(savedWindowBounds(path), normal);
    }

    // #62 round 4 (exordy review on the round-3 size guard): a user-settled
    // normal window may legitimately fill the screen - rejecting every
    // screen-filling WindowNoState as a WM hop therefore also rejects real
    // user moves of such a window made while the exit gate is open, and the
    // detach/gate-release persists the pre-move bounds. Only the frame that
    // still wears the fullscreen snapshot while the release restore sequence
    // is in flight is a transition; a moved screen-filling frame is settled
    // and must be recaptured.
    void fullscreenExitFromScreenFillingNormalRecapturesUserMoveMadeDuringTheGate()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const auto path = directory.filePath("preferences.ini");
        NativePreferences preferences(path);
        QWindow window;
        auto teardown = qScopeGuard([&preferences, &window] {
            preferences.attachWindow(nullptr);
            window.close();
        });
        preferences.attachWindow(&window);
        window.show(); QVERIFY(QTest::qWaitForWindowExposed(&window));
        const auto available = QGuiApplication::primaryScreen()->availableGeometry();
        window.setGeometry(QRect(available.x() + 60, available.y() + 40, 900, 650));
        QTest::qWait(700);
        // A normal (not maximized) window the user stretched to fill the screen.
        const QRect filled(available.topLeft(), available.size());
        window.setGeometry(filled);
        QTest::qWait(700); // outlast the 350 ms save debounce
        QCOMPARE(savedWindowBounds(path), filled);
        QVERIFY(!QSettings(path, QSettings::IniFormat).value("window/maximized").toBool());
        QTest::keyClick(&window, Qt::Key_F11);
        QTRY_VERIFY_WITH_TIMEOUT(window.visibility() == QWindow::FullScreen, 5000);
        QTest::qWait(700); // let the enter gate settle before starting the exit
        QCOMPARE(savedWindowBounds(path), filled);
        QTest::keyClick(&window, Qt::Key_F11);
        QTRY_VERIFY_WITH_TIMEOUT(window.visibility() != QWindow::FullScreen, 5000);
        // The user drags the screen-filling window to a new origin while the
        // exit gate is still open (the transient restore re-armed the settle).
        // The moved bounds are legitimate and must be persisted, not rejected
        // as a fullscreen shape the restore has not left behind.
        const QRect moved(available.x() + 180, available.y() + 60,
            available.width(), available.height());
        window.setGeometry(moved);
        QTRY_COMPARE_WITH_TIMEOUT(window.geometry(), moved, 5000);
        preferences.attachWindow(nullptr); // quit-style immediate save mid-gate
        QCOMPARE(savedWindowBounds(path), moved);
    }

    // #62 round 5 (review cid 4611449708): the enter side of the R4 release
    // guard. On a NORMAL (non-maximized) window the WM may deliver the
    // fullscreen configure BEFORE the fullscreen state atom, and an immediate
    // save (aboutToQuit/detach) landing inside that transient used to persist
    // the fullscreen rectangle as the settled normal bounds: the round-3
    // screen-size guard only rejected the enter hop when maximized. The frame
    // is driven deterministically the same way R3's exit case drives its
    // transient (openbox coalesces configure+state and Qt confirms the
    // fullscreen state locally at showFullScreen, so the natural WM order is
    // never geometry-first): F11 starts the enter, then the fullscreen shape
    // arrives while windowState has no FullScreen atom, then the save fires.
    void fullscreenEnterFromNormalMidTransitionSaveKeepsNormalBounds()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const auto path = directory.filePath("preferences.ini");
        NativePreferences preferences(path);
        QWindow window;
        auto teardown = qScopeGuard([&preferences, &window] {
            preferences.attachWindow(nullptr);
            window.close();
        });
        preferences.attachWindow(&window);
        window.show(); QVERIFY(QTest::qWaitForWindowExposed(&window));
        const auto available = QGuiApplication::primaryScreen()->availableGeometry();
        const auto screen = QGuiApplication::primaryScreen()->geometry();
        const QRect normal(available.x() + 55, available.y() + 35, 840, 600);
        window.setGeometry(normal);
        QTest::qWait(700); // outlast the save debounce: settled normal on disk
        QCOMPARE(savedWindowBounds(path), normal);
        QTest::keyClick(&window, Qt::Key_F11); // enter starts: gate closes
        // Transition frame: the fullscreen geometry is present while no
        // FullScreen state atom has been reported (state is back at NoState).
        window.showNormal();
        window.setGeometry(screen);
        QVERIFY(window.windowState() != Qt::WindowFullScreen);
        preferences.attachWindow(nullptr); // the aboutToQuit seam: immediate save
        // The transition frame must not overwrite the settled normal bounds.
        QCOMPARE(savedWindowBounds(path), normal);
    }

    // #62 round 6 (review cid 4612931182): the enter flag is cleared on
    // recapture, not on the FullScreen state signal, so a WM restore that
    // lands after the state atom but before the gate's recapture stays
    // classified as an enter hop and an immediate save drops its bounds.
    // The restore must be judged settled user geometry the moment the
    // FullScreen observation arrives: F11 enters (Qt confirms the atom
    // synchronously), the window is restored at a normal rect that differs
    // from the settled one, and the detach save must persist the restore.
    void fullscreenEnterWmRestoreAfterStateSignalDuringGatePersistsRestoredBounds()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const auto path = directory.filePath("preferences.ini");
        NativePreferences preferences(path);
        QWindow window;
        auto teardown = qScopeGuard([&preferences, &window] {
            preferences.attachWindow(nullptr);
            window.close();
        });
        preferences.attachWindow(&window);
        window.show(); QVERIFY(QTest::qWaitForWindowExposed(&window));
        const auto available = QGuiApplication::primaryScreen()->availableGeometry();
        const QRect normal(available.x() + 70, available.y() + 45, 850, 610);
        window.setGeometry(normal);
        QTest::qWait(700); // outlast the save debounce: settled normal on disk
        QCOMPARE(savedWindowBounds(path), normal);
        QTest::keyClick(&window, Qt::Key_F11); // enter starts: gate closes
        QTRY_VERIFY_WITH_TIMEOUT(window.windowState() == Qt::WindowFullScreen, 5000);
        // The WM restores the window at a new normal rect while the enter
        // gate is still open (the restore stops the settle backstop from
        // firing, so the save below lands mid-gate by construction).
        const QRect restored(available.x() + 140, available.y() + 70, 760, 640);
        window.showNormal();
        window.setGeometry(restored);
        QVERIFY(window.windowState() != Qt::WindowFullScreen);
        QCOMPARE(window.geometry(), restored);
        preferences.attachWindow(nullptr); // the aboutToQuit seam: immediate save
        // The restore is settled user geometry, not an enter hop: its
        // bounds must be persisted, not dropped with the transition.
        QCOMPARE(savedWindowBounds(path), restored);
    }

    // #62 round 6 (review thread cid 4611449708): the gate-cap release must
    // not persist the fullscreen transition frame as normal bounds. The cap
    // cleared the enter guard one statement before recapture, so when the
    // window still wears the fullscreen shape while its state transition
    // lags (NoState with the fullscreen rect, the order R5 reproduced), the
    // recapture on cap expiry saves the fullscreen rect as the normal
    // geometry. The settled normal bounds must survive the cap expiry.
    void fullscreenEnterGateCapExpiryKeepsTransitionFrameOutOfSavedBounds()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        const auto path = directory.filePath("preferences.ini");
        NativePreferences preferences(path);
        QWindow window;
        auto teardown = qScopeGuard([&preferences, &window] {
            preferences.attachWindow(nullptr);
            window.close();
        });
        preferences.attachWindow(&window);
        window.show(); QVERIFY(QTest::qWaitForWindowExposed(&window));
        const auto available = QGuiApplication::primaryScreen()->availableGeometry();
        const auto screen = QGuiApplication::primaryScreen()->geometry();
        const QRect normal(available.x() + 50, available.y() + 30, 830, 620);
        window.setGeometry(normal);
        QTest::qWait(700); // outlast the save debounce: settled normal on disk
        QCOMPARE(savedWindowBounds(path), normal);
        QTest::keyClick(&window, Qt::Key_F11); // enter starts: gate closes
        // Transition frame: the fullscreen shape is present while the state
        // is back at NoState, so the transition never settles and only the
        // 1500 ms gate cap ends the gate.
        window.showNormal();
        window.setGeometry(screen);
        QVERIFY(window.windowState() != Qt::WindowFullScreen);
        // Outlast the cap plus the debounced save it schedules.
        QTest::qWait(1500 + 1200);
        QVERIFY2(savedWindowBounds(path) == normal,
            "the gate-cap release persisted the fullscreen transition frame as the normal bounds");
    }
