        QCOMPARE(filename->property("text").toString(), QString("session-logs.json"));
        QTRY_VERIFY_WITH_TIMEOUT(dialogButton("Save"), 4000);
        auto *saveButton=dialogButton("Save");
        QSignalSpy saveAccepted(saveDialog, SIGNAL(accepted()));
