        const auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard && !closeIncubatedTestWindow(engine, guard.data())) QTest::qFail("Body copy teardown", __FILE__, __LINE__);
        });
