    void topicContextMenuActionFailureSurfacesErrorNotice()
    {
        // Review finding 4652383415: the read/done/notification rows close
        // the menu before dispatch, so a failed write needs its own notice -
        // only the rename dialog had an error surface before this case.
        TopicMenuScene scene;
        const auto notice = [&] { return scene.popup(QStringLiteral("topicActionErrorToast")); };
        const auto noticeText = [&] {
            auto *toast = notice();
            return toast ? toast->property("noticeText").toString() : QString();
        };
        // Mark as read fails (unread Backlog row).
        scene.openMenu(QStringLiteral("topic-") + scene.extraTopic);
        auto *mark = scene.row(QStringLiteral("topicMarkReadAction"));
        QVERIFY(mark);
        scene.failNextAction = true;
        click(scene.window.data(), mark);
        QTRY_COMPARE(scene.readPosts, 1);
        QVERIFY(!scene.menuOpen());
        QTRY_VERIFY_WITH_TIMEOUT(notice() && notice()->property("opened").toBool(), 4000);
        QCOMPARE(noticeText(), QStringLiteral("Could not mark the topic as read. Please try again."));
        QMetaObject::invokeMethod(notice(), "close");
        // Notification level switch fails.
        scene.openMenu(QStringLiteral("topic-") + topicId);
        auto *followed = scene.row(QStringLiteral("topicNotifSegment-followed"));
        QVERIFY(followed);
        scene.failNextAction = true;
        click(scene.window.data(), followed);
        QTRY_COMPARE(scene.notifPosts, 1);
        QTRY_VERIFY_WITH_TIMEOUT(notice() && notice()->property("opened").toBool(), 4000);
        QCOMPARE(noticeText(), QStringLiteral("Could not update the topic notifications. Please try again."));
        QMetaObject::invokeMethod(notice(), "close");
        // Done toggle fails.
        scene.openMenu(QStringLiteral("topic-") + topicId);
        auto *done = scene.row(QStringLiteral("topicDoneAction"));
        QVERIFY(done);
        scene.failNextAction = true;
        click(scene.window.data(), done);
        QTRY_COMPARE(scene.donePosts, 1);
        QTRY_VERIFY_WITH_TIMEOUT(notice() && notice()->property("opened").toBool(), 4000);
        QCOMPARE(noticeText(), QStringLiteral("Could not update the topic. Please try again."));
        // The guard released: the same action is immediately actionable again.
        QMetaObject::invokeMethod(notice(), "close");
        scene.openMenu(QStringLiteral("topic-") + topicId);
        QVERIFY(scene.row(QStringLiteral("topicDoneAction"))->property("enabled").toBool());
        QTest::keyClick(scene.window.data(), Qt::Key_Escape);
        QTRY_VERIFY(!scene.menuOpen());
    }

    void topicContextMenuReopenDuringInFlightActionStillSurfacesFailure()
    {
        // exordy finding 4652383415 (round 2): reopening the menu before an
        // in-flight write settles must not swallow that write's failure
        // notice. The dispatch identity therefore has to be SNAPSHOTTED at
        // dispatch time - open() re-points the live target (and used to clear
        // the pending notice tag), so matching a late reply against the live
        // target loses the failure whenever any menu reopen happens in flight.
        TopicMenuScene scene;
        const auto notice = [&] { return scene.popup(QStringLiteral("topicActionErrorToast")); };
        const auto noticeText = [&] {
            auto *toast = notice();
            return toast ? toast->property("noticeText").toString() : QString();
        };
        const auto reopen = [&](const QString &rowName) {
            scene.openMenu(rowName);
            QTRY_VERIFY(scene.menuOpen());
            QTest::keyClick(scene.window.data(), Qt::Key_Escape);
            QTRY_VERIFY(!scene.menuOpen());
        };
        // Scenario 1: the SAME row's menu is reopened while the read write is
        // still in flight; the held 500 must still surface its notice.
        scene.openMenu(QStringLiteral("topic-") + scene.extraTopic);
        auto *mark = scene.row(QStringLiteral("topicMarkReadAction"));
        QVERIFY(mark);
        scene.deferNextAction = true;
        scene.failNextAction = true;
        click(scene.window.data(), mark);
        QTRY_COMPARE(scene.readPosts, 1);
        QVERIFY(!scene.menuOpen());
        reopen(QStringLiteral("topic-") + scene.extraTopic);
        scene.release();
        QTRY_VERIFY_WITH_TIMEOUT(notice() && notice()->property("opened").toBool(), 4000);
        QCOMPARE(noticeText(), QStringLiteral("Could not mark the topic as read. Please try again."));
        QMetaObject::invokeMethod(notice(), "close");
        // Scenario 2: the menu is reopened on a DIFFERENT row while the read
        // write is in flight; the live-target move must not steal the pending
        // identity either.
        scene.openMenu(QStringLiteral("topic-") + scene.extraTopic);
        auto *mark2 = scene.row(QStringLiteral("topicMarkReadAction"));
        QVERIFY(mark2);
        scene.deferNextAction = true;
        scene.failNextAction = true;
        click(scene.window.data(), mark2);
        QTRY_COMPARE(scene.readPosts, 2);
        reopen(QStringLiteral("topic-") + topicId);
        scene.release();
        QTRY_VERIFY_WITH_TIMEOUT(notice() && notice()->property("opened").toBool(), 4000);
        QCOMPARE(noticeText(), QStringLiteral("Could not mark the topic as read. Please try again."));
        QMetaObject::invokeMethod(notice(), "close");
    }

    void topicContextMenuConcurrentSameActionKeepsBothNotices()
    {
        // exordy finding 4652383415 (round 3): concurrent actions of the SAME
        // kind on DIFFERENT topics must each keep their own failure notice.
        // A pending-notice store keyed only by action lets the second
        // dispatch overwrite the first topic's identity, so the first failed
        // reply can no longer match its dispatch and is silently dropped.
        // Both replies are held and settled ONE AT A TIME: the first topic's
        // failure must open a notice while the second write is still in
        // flight, and the second topic's failure must open one as well.
        TopicMenuScene scene;
        const auto notice = [&] { return scene.popup(QStringLiteral("topicActionErrorToast")); };
        const auto noticeText = [&] {
            auto *toast = notice();
            return toast ? toast->property("noticeText").toString() : QString();
        };
        const auto countNotices = [&] {
            QList<QObject *> found;
            TopicMenuScene::collect(scene.window.data(),
                QStringLiteral("sidebarTopicMenuSurface"), found);
            for (auto *item : found)
                return item->property("countSurfacedNotices").toInt();
            return -1;
        };
        QCOMPARE(countNotices(), 0);
        // First dispatch: Done on the Backlog topic, reply held (500).
        scene.openMenu(QStringLiteral("topic-") + scene.extraTopic);
        auto *firstDone = scene.row(QStringLiteral("topicDoneAction"));
        QVERIFY(firstDone);
        scene.deferNextAction = true;
        scene.failNextAction = true;
        click(scene.window.data(), firstDone);
        QTRY_COMPARE(scene.donePosts, 1);
        // Second dispatch while the first is still in flight: same action
        // kind (toggle_done) on the MAIN topic - this overwrite used to
        // steal the only pending slot.
        scene.openMenu(QStringLiteral("topic-") + topicId);
        auto *secondDone = scene.row(QStringLiteral("topicDoneAction"));
        QVERIFY(secondDone);
        scene.deferNextAction = true;
        scene.failNextAction = true;
        click(scene.window.data(), secondDone);
        QTRY_COMPARE(scene.donePosts, 2);
        QVERIFY(!scene.menuOpen());
        // Settle the FIRST held failure while the second write is in flight:
        // the notice for the Backlog topic must surface on its own merit.
        scene.releaseOne();
        QTRY_VERIFY_WITH_TIMEOUT(countNotices() >= 1, 4000);
        QCOMPARE(noticeText(), QStringLiteral("Could not update the topic. Please try again."));
        QMetaObject::invokeMethod(notice(), "close");
        // The second failure then settles and keeps its own notice.
        scene.releaseOne();
        QTRY_VERIFY_WITH_TIMEOUT(countNotices() >= 2, 4000);
        QCOMPARE(noticeText(), QStringLiteral("Could not update the topic. Please try again."));
        QMetaObject::invokeMethod(notice(), "close");
    }

