    // Issue #661: reference composer action placement
    // (docs/NATIVE_DESKTOP_COMPOSER_LAYOUT.md). The reference compact composer
    // keeps only attach + emoji in the field (message-composer.ui.tsx:1949-1960)
    // and the poll trigger belongs to the expanded toolbar right after the
    // emoji trigger (message-composer-toolbar.ui.tsx:145-151).
    void composerPollTriggerLivesInTheExpandedToolbar()
    {
        QTemporaryDir directory; QVERIFY(directory.isValid());
        WindowChannelFixture fixture;
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
        NativePreferences preferences(directory.filePath("composer-layout.ini"));
        preferences.setLocale("en"); preferences.setMode("light");
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences, nullptr, nullptr);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard && !closeIncubatedTestWindow(engine, guard.data()))
                QTest::qFail("Composer layout window did not settle before engine teardown", __FILE__, __LINE__);
        });
        window->resize(1440, 900); QVERIFY(QTest::qWaitForWindowExposed(window));
        window->requestActivate(); QVERIFY(QTest::qWaitForWindowActive(window));
        session.login(fixture.server.origin(), "synthetic", "synthetic");
        QTRY_COMPARE(session.projects().size(), 1); session.selectProject(projectId);
        QTRY_COMPARE(controller.streams().size(), 1);
        QTRY_VERIFY(controller.channelMembersVerified());
        preferences.setOwner(controller.ownerKey());
        click(window, visibleItem(window->contentItem(), "stream-" + streamId));
        QTRY_COMPARE(controller.topics().size(), 1);
        click(window, visibleItem(window->contentItem(), "topic-" + topicId));
        QTRY_VERIFY(controller.selectedStream() == streamId && controller.selectedTopic() == topicId);
        QTRY_VERIFY(!controller.busy());
        auto *content = window->contentItem();
        const auto rectOf = [&](const QString &name) {
            auto *target = visibleItem(content, name);
            if (!target) return QRectF();
            return QRectF(target->mapToItem(window->contentItem(), QPointF()), QSizeF(target->width(), target->height()));
        };
        // Collapsed (the reference default shape): the field keeps attach and
        // emoji, and no poll trigger exists anywhere in the window.
        QVERIFY(!preferences.composerToolbarExpanded());
        QTRY_VERIFY(visibleItem(content, "attachButton"));
        QTRY_VERIFY(visibleItem(content, "composerEmojiButton"));
        QVERIFY(!visibleItem(content, "pollButton"));
        // Expanded: the triggers render inside the toolbar row below the
        // input, strictly ordered attach < emoji < poll (#215 toolbar order).
        click(window, visibleItem(content, "composerToolbarExpand"));
        QTRY_VERIFY(visibleItem(content, "composerToolbarRow"));
        QTRY_VERIFY(visibleItem(content, "pollButton"));
        QTest::qWait(50); // wait for the rendered scene, not just visibility
        const auto toolbarRect = rectOf("composerToolbarRow");
        const auto attachRect = rectOf("attachButton");
        const auto emojiRect = rectOf("composerEmojiButton");
        const auto pollRect = rectOf("pollButton");
        QVERIFY2(toolbarRect.contains(attachRect), "attach trigger must sit inside the toolbar row");
        QVERIFY2(toolbarRect.contains(emojiRect), "emoji trigger must sit inside the toolbar row");
        QVERIFY2(toolbarRect.contains(pollRect), "poll trigger must sit inside the toolbar row");
        QVERIFY(attachRect.left() < emojiRect.left());
        QVERIFY(emojiRect.left() < pollRect.left());
        QCOMPARE(pollRect.size(), QSizeF(32, 32));
        // The create-poll dialog still opens from the toolbar trigger.
        click(window, visibleItem(content, "pollButton"));
        auto *dialog = window->findChild<QObject *>("pollCreateDialog"); QVERIFY(dialog);
        QTRY_VERIFY(dialog->property("visible").toBool());
        QMetaObject::invokeMethod(dialog, "close");
        // Collapsing hides the poll trigger again (reference: the collapsed
        // toolbar renders nothing) while the field regains attach + emoji.
        click(window, visibleItem(content, "composerToolbarCollapse"));
        QTRY_VERIFY(!visibleItem(content, "pollButton"));
        QTRY_VERIFY(visibleItem(content, "attachButton"));
        QTRY_VERIFY(visibleItem(content, "composerEmojiButton"));
    }

    // #770 deterministic teardown seam. Scene destructors pump the event loop
    // (frame/focus acknowledgement inside closeIncubatedTestWindow) AFTER the
    // case's later-declared locals are destroyed. Before the fix, a client
    // request landing in that pump re-entered the case's [ref]-captured
    // handler chain - calling the destroyed `base` std::function copy - and
    // aborted the process (std::bad_function_call / wild call: the CI failure
    // family in issue #770). Each scene now quiesces its mock server before
    // the pump, so a late request only ever sees the safe empty fallback.
    void lateTeardownRequestDoesNotReenterDeadCaseLocals()
    {
        const int servedBefore = g_lateTeardownServed.load();
        {
            ChannelInfoWindowScene scene(true,
                QStringLiteral("workspace.topic_summary_settings.manage"));
            // The oracle counts SERVER-SIDE dispatch: the late request must
            // actually reach the mock server's quiesced fallback after the
            // case locals died. A client-side connect counter would pass even
            // when the request is never served (exo-review on #772).
            scene.fixture.server.quiescedRequestCount = &g_lateTeardownServed;
            QList<QJsonObject> saveBodies; // already dead when the late request lands
            const auto base = scene.fixture.server.handler;
            scene.fixture.server.handler = [&](const Request &request) -> Response {
                saveBodies.append(request.body); // dangling after scope exit
                return base(request);
            };
            // A raw client parented to the scene's controller outlives the case
            // locals; the 0 ms timer can only fire once the destructor starts
            // pumping, so the request provably arrives after `base` died.
            const quint16 port = quint16(scene.fixture.server.serverPort());
            auto *late = new QTcpSocket(&scene.controller);
            QObject::connect(late, &QTcpSocket::connected, late, [late] {
                const QByteArray head =
                    "GET /messages/?topic_uuid=00000000-0000-4000-8000-000000000000 HTTP/1.1\r\n"
                    "Host: 127.0.0.1\r\nContent-Length: 0\r\n\r\n";
                late->write(head);
            });
            QTimer::singleShot(0, late, [late, port] {
                late->connectToHost(QHostAddress::LocalHost, port);
            });
        }
        QTRY_VERIFY2(g_lateTeardownServed.load() > servedBefore,
            "the late request must be served by the quiesced mock server (fallback path exercised)");
    }

    void windowEdgeOutlineFramesRestoredWindowAndClearsOnMaximize()
    {
        // #720 acceptance: a restored window reads against a white backdrop (the
        // palette-edge ring frames it and its top edge is the title-bar seam),
        // and maximized mode gains no extra inset because the ring steps aside.
        QTemporaryDir directory; QVERIFY(directory.isValid());
        ApiClient api(nullptr, true); Session session(&api); NativeController controller(&api, &session);
        NativePreferences preferences(directory.filePath("appearance.ini")); preferences.setLocale("en");
        QQmlApplicationEngine engine; loadNativeUi(engine, &controller, &preferences);
        auto *window = qobject_cast<QQuickWindow *>(engine.rootObjects().value(0)); QVERIFY(window);
        const auto close = qScopeGuard([&engine, guard = QPointer<QQuickWindow>(window)] {
            if (guard && !closeIncubatedTestWindow(engine, guard.data()))
                QTest::qFail("edge outline teardown", __FILE__, __LINE__);
        });
        QVERIFY(QTest::qWaitForWindowExposed(window));
        window->resize(980, 720);
        auto *outline = window->findChild<QObject *>("windowEdgeOutline");
        QVERIFY2(outline, "a restored window must paint the palette-edge perimeter ring");
        QVERIFY(outline->property("visible").toBool());
        QCOMPARE(outline->property("edgeWidth").toReal(), 1.0);
        // Overlay contract: the ring exactly covers the content area, so it adds
        // no layout inset and re-frames itself for free while resizing.
        QTRY_VERIFY(qRound(outline->property("width").toReal()) == window->width()
            && qRound(outline->property("height").toReal()) == window->height());
        // The edge is the palette border token, so every palette and the dark
        // mode keep the treatment theme-appropriate.
        QVERIFY(outline->property("edgeColor").value<QColor>()
            == QColor(window->property("colors").toMap().value("border-subtle").toString()));
        // Maximized: the screen frame is the edge, so no fake inset is drawn.
        window->showMaximized();
        QTRY_VERIFY_WITH_TIMEOUT(!outline->property("visible").toBool(), 5000);
        window->showNormal();
        QTRY_VERIFY_WITH_TIMEOUT(outline->property("visible").toBool(), 5000);
    }

